WordHunterWoW_QuestEN[37256] = { title = "They Came From the Sea", description = "You're looking for Prince Farondis?\n\n<The ghostly elf narrows her eyes warily.>\n\nI can take you to Farondis... but first things first. These naga attacked suddenly. They take orders from one called Zarrin, in the low hills to the west.\n\nHelp me take Zarrin's head, and you'll have my ear.", objectives = "Obtain the Head of Fathom-Commander Zarrin, and slay 8 of his naga troops.", progress = "<The nightwatcher looks at you expectantly.>", completion = "<Idri stares at the ugly head.>\n\nYes, that's him." }
WordHunterWoW_QuestEN[37257] = { title = "Our Very Bones", description = "You seek the Tidestone of Golganneth?\n\nYes, I know where it lies. It is in a place to which I prefer not to return.\n\nYou may be of use to me. In the midst of this naga attack, those horrid fish-men flopped their way onto my lands and raided our graveyards. They steal the bones of our ancestors, and indeed, the very bones of my people.\n\nHelp me bring some solace to my people. Then I shall tell you more about the Tidestone.", objectives = "Obtain 55 Pilfered Night Elf Bones.", progress = "My people may not care much for me, but that will not stop me from caring for them.", completion = "Our bones are all we have left of an existence we left behind a long time ago.\n\n<The prince stares intently into your eyes.>\n\nStay with me, <class>. I will help you find your Tidestone." }
WordHunterWoW_QuestEN[37259] = { title = "A Worthy Challenge: Teron'gor", description = "<name>, I need you to assemble a fearless group and lead them into the depths of Auchindoun. Activate the Challenger's Orb, and cleanse Auchindoun of Teon'gor's evil presence.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", objectives = "Complete the Auchindoun Challenge Mode.", completion = "<name>, you've done a great service. May the souls of Auchindoun remain at peace with the threat of Teron'gor eliminated." }
WordHunterWoW_QuestEN[37260] = { title = "A Worthy Challenge: Gug'rokk", description = "<name>, I need you to assemble a formidable group and head into the depths of the Bloodmaul Slag Mines. Activate the Challenger's Orb, and free the miners of Gug'rokk's tyrannical rule.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", objectives = "Complete the Bloodmaul Slag Mines Challenge Mode.", completion = "<name>, you've done a great service. The families of the rescued miners will never be able to thank you enough for eliminating Gug'rokk and his slavers." }
WordHunterWoW_QuestEN[37261] = { title = "A Worthy Challenge: Skylord Tovra", description = "<name>, I need you to assemble an elite group to infiltrate the Grimrail Depot. Activate the Challenger's Orb, and make your way to the Grimrail and put an end to it and Skylord Tovra's air support.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", objectives = "Complete the Grimrail Depot Challenge Mode.", completion = "<name>, you've done a great service. Eliminating Skylord Tovra's rylak escorts and disrupting the Grimrail will save an innumerable amount of lives." }
WordHunterWoW_QuestEN[37262] = { title = "A Worthy Challenge: Skullok, Son of Gruul", description = "<name>, I need you to assemble a hardy group to breach the Iron Docks. Activate the Challenger's Orb, and put a stop to the Iron Horde's training facility and their subjugation of Draenor's mightiest, including Skullok, Son of Gruul.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", objectives = "Complete the Iron Docks Challenge Mode.", completion = "<name>, you've done a great service. Taking down one of Draenor's great giants is regrettable, but letting Skullok, Son of Gruul, remain a tool of the Iron Horde would have led to great distruction." }
WordHunterWoW_QuestEN[37263] = { title = "A Worthy Challenge: Ner'zhul", description = "<name>, I need you to assemble a resolute group of warriors and venture into the Shadowmoon Burial Grounds. Activate the Challenger's Orb, and put a stop to Ner'zhul's communion with the void before he takes all of Draenor with him.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", objectives = "Complete the Shadowmoon Burial Grounds Challenge Mode.", completion = "<name>, you've done a great service. Putting an end to Ner'zhul and his deathly rituals will allow many to sleep better at night." }
WordHunterWoW_QuestEN[37264] = { title = "A Worthy Challenge: High Sage Viryx", description = "<name>, I need you to assemble a determined group of adventures and venture into Skyreach. Activate the Challenger's Orb, reach the summit and put an end to High Sage Viryx and her super weapon.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", objectives = "Complete the Skyreach Challenge Mode.", completion = "<name>, you've done a great service. If not for you, all of Draenor may have withered under High Sage Viryx's rule." }
WordHunterWoW_QuestEN[37265] = { title = "A Worthy Challenge: Yalnu", description = "<name>, I need you to assemble a resolute group of adventures and journey in to The Everbloom. Activate the Challenger's Orb, penetrate the depths of The Everbloom and put a stop to Yalnu and his ambitions.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", objectives = "Complete The Everbloom Challenge Mode.", completion = "<name>, you've done a great service. Your efforts to stop Yalnu may not only have saved our outpost but all of Azeroth as well." }
WordHunterWoW_QuestEN[37266] = { title = "A Worthy Challenge: Warlord Zaela", description = "<name>, I need you to assemble a group of stalwart adventures and journey back to Azeroth and Upper Blackrock Spire. Activate the Challenger's Orb, enter the old home of the Blackrock clan and defeat the Ironmarch Vanguard and their new ally, Warlord Zaela.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", objectives = "Complete the Upper Blackrock Spire Challenge Mode.", completion = "<name>, you've done a great service. Defeating the Ironmarch Vanguard at Upper Blackrockspire is a major blow to the Iron Horde and Azeroth can rest a bit more knowing Warlord Zaela's bid for revenge has been permanently dealt with." }
WordHunterWoW_QuestEN[37268] = { title = "Shadowmoon Invasion! BETA", description = "Scouts report that the Shadowmoon Clan is buzzing like a kicked hornets' nest. Time again to earn our pay, Commander?", objectives = "Repel the Shadowmoon Clan invasion of your garrison.\n\n(Speak with Sergeant Crowler again to begin)", progress = "Commander, we'll assemble the troops at your command.", completion = "Nothing like a little righteous bloodshed, to shake the chill from these old bones." }
WordHunterWoW_QuestEN[37269] = { title = "Shadowmoon Invasion! BETA", description = "Scouts say the Shadowmoon Clan looms close, ready with their necromancy. If I die and rise again, Commander, finish me quickly. I don't want to be a ghoul.", objectives = "Repel the Shadowmoon invasion of your garrison.\n\n(Speak with Sergeant Grimjaw again to begin)", completion = "You were a blaze amongst our foes, Commander. It looks like we'll see another dawn in Draenor." }
WordHunterWoW_QuestEN[37270] = { title = "Alchemy Experiment", description = "", objectives = "I've been experimenting again today, and I've come up with some potion formulations that might suit you, commander. Would you like to try one?" }
