WordHunterWoW_QuestEN[37281] = { title = "Standing United", description = "", objectives = "I mean nae offense, commander, but I don't trust yer forces tae keep ya safe from a Shattered Hand assassination attempt on yer life.\n\nIf it's agreeable to ye, I'd like tae join yer garrison and keep a watch on the scoundrels." }
WordHunterWoW_QuestEN[37282] = { title = "COLISEUM WINNER FLAG (MONUMENT FLAG-NO RESET)", description = "", objectives = "" }
WordHunterWoW_QuestEN[37283] = { title = "COLISEUM LOSER FLAG (DAILY RESET)", description = "", objectives = "" }
WordHunterWoW_QuestEN[37284] = { title = "Da Big Score", description = "I know, I know. I be givin' ya these for ya treasures, but now I be wantin' dem back. It be complicated, mon. Do ya want da gold or not?", objectives = "Obtain Dingy Iron Coins for Griftah.", progress = "So you've got them?", completion = "Oh, ya got dem for me? Excellent. Here's ya money." }
WordHunterWoW_QuestEN[37285] = { title = "If You're Sure", description = "You sure be collectin' a lot of treasures. Dey will be worth more next week, but I can take 'em off your hands.", objectives = "Give surplus Dingy Iron Coins to Griftah.", progress = "Here you go.", completion = "Here ya go! Instant gratification's da best gratification!" }
WordHunterWoW_QuestEN[37286] = { title = "The Bloodshed Never Ends", description = "You are insatiable, gladiator! Let none doubt your voracious appetite for destruction and death!\n\nImperator Mar'gok will be very pleased to see you battling upon the arena floor of the Coliseum once more!\n\nAs before, I will accept nothing less than 100 lives!\n\nKill or be killed, gladiator!", objectives = "Kill 100 Gladiators at the Coliseum in Highmaul.\n\nYou may access the Coliseum by talking to Kharg at Highmaul or Boneslag at your Gladiator's Sanctum.", completion = "To the victor go the spoils! All hail <name>!" }
WordHunterWoW_QuestEN[37287] = { title = "Cleaning House", description = "Not long ago, a new recruit showed up by the name o' Jacob Anders. He's been trouble since he got here, always drinkin' and pickin' fights, but he crossed the line this time.\n\nOne o' our patrols spotted him tradin' intel with the Horde - he's a traitor, commander! I thought ye would want tae deal with him personally.\n\nHe was out drinkin' by the water last time I saw him, and I'd bet me pappy's beard he's still there.", objectives = "Deal with Jacob Anders at Southport.", completion = "I think ye did the right thing, commander." }
WordHunterWoW_QuestEN[37288] = { title = "Resources in Ashran", description = "Bodrick has mentioned to me that you have acquired some interesting construction notes in your forays out there. A construction guide or assembly notes perhaps?\n\nYou should speak with Kinkade Jacobs in Stormshield. She is willing to exchange finished blueprints for such things.", objectives = "Speak with Kinkade Jacobs at Stormshield in Ashran.", completion = "Oh you have some blueprint texts for me? That's great!\n\nLet's do some business!" }
WordHunterWoW_QuestEN[37289] = { title = "Shadowmoon Invasion!", description = "Your arrival couldn't be more timely, commander.\n\nShadowmoon raiders have been spotted closing in on the garrison.\n\nYou repelled their advances at Teluuna Observatory, and created chaos at Shaz'gul.\n\nNow, they surely seek retribution. They will throw everything they have at us.\n\nI have the entire garrison on high alert. Are you ready to face them?", objectives = "Repel the Shadowmoon clan invasion of your garrison.\n\n(Speak with Sergeant Crowler again to begin)", progress = "Time to shine a light on these shadows!", completion = "I don't think they were ready for that. The Shadowmoon will think twice before attacking us again." }
WordHunterWoW_QuestEN[37290] = { title = "Upgrades in Ashran", description = "You got some construction guides or assembly notes on ya? Oh man that's good news!\n\nI know this guy in Ashran, goes by Torgg Flexington. He's got finished blueprints we need!\n\nGo talk to this guy and bring back some good stuff for us to build, ok?", objectives = "Speak with Torgg Flexington at Warspear in Ashran.", completion = "Oh YEAH buddy! We can work something out. I got plenty of stuff for you to buy!" }
WordHunterWoW_QuestEN[37291] = { title = "Thunderlord Invasion!", description = "Your timing could not have been better.\n\nYour scouts have reported the approach of a large Thunderlord army.\n\nMy clan can ride out and assist in severing their reinforcements, but you will need to see to the defense of your fort against the bulk of their forces.\n\nSergeant Grimjaw awaits your command.", objectives = "Repel the Thunderlord invasion.", progress = "The Frostwolves stand ready.", completion = "Well fought, commander. Now to strike back before the Thunderlord can recover." }
WordHunterWoW_QuestEN[37292] = { title = "Not In Your Army", description = "Your men caught one of da new recruits,  talking with da alliance behind your back. She be a traitor, boss-mon! She be a danger to everything you've worked so hard for.\n\nWe have a wyvern ready to be takin' her to your garrison for proper punishment. I thought you would be wantin' to deal with da scoundrel personally.\n\nI last be seein' her on the back road out of Axefall.", objectives = "Deal with Rorka at Axefall.", progress = "Is da traitor ready to leave, commander?", completion = "You be makin' the right call, commander. There be no room for her kind in your ranks." }
WordHunterWoW_QuestEN[37293] = { title = "Clearing the Mist", description = "<The troll's skin looks pale. Beads of sweat dot his brow.>\n\nI know you owe me nouting, but if you be willin' ta help me, I have a favor to ask.\n\nTa da north, dere be da creature dat is da cause a' dis poisonous mist.\n\nOnly da heart a' dis beast has da power ta neutralize da toxins in my body.\n\nYa may have ta kill some a dose crawlers while you're at it.\n\nIf ya feel weak from da poison, eat some a dose glowing mushrooms ta counter da effects.", objectives = "Kill 8 Cerulean Crawlers and collect the Overgrown Heart.", progress = "I ain't feelin' so good.", completion = "Yes! Dat be da heart! You did it..." }
WordHunterWoW_QuestEN[37294] = { title = "COLISEUM BOOBY PRIZE FLAG (DAILY RESET)", description = "", objectives = "" }
WordHunterWoW_QuestEN[37295] = { title = "Kill Rylai Crestfall", description = "", objectives = "" }
WordHunterWoW_QuestEN[37296] = { title = "A Lack of Wasps", description = "The stings! These cursed wasps drone day and night and their constant aggression taxes me so.\n\nI shall do nothing about your offer until these nuisances are dealt with.", objectives = "Kill 8 Widow Wasps.", progress = "Wasps are truly despicable things.", completion = "Perhaps my rituals will be undisturbed for a few nights at least. Your offer is intriguing and I think we can come to an agreement." }
