WordHunterWoW_QuestEN[37305] = { title = "Bronze Victory", description = "Surrounded as we are, we cannot be weak. We must win every battle, and win them decisively.", objectives = "Surrounded as we are, we cannot be weak. We must win every battle, and win them decisively.", progress = "Surrounded as we are, we cannot be weak. We must win every battle, and win them decisively.", completion = "With every victory, or claim here grows more strong." }
WordHunterWoW_QuestEN[37306] = { title = "Silver Victory", description = "The harder we beat our enemies, the less quickly they'll return.", objectives = "The harder we beat our enemies, the less quickly they'll return.", progress = "The harder we beat our enemies, the less quickly they'll return.", completion = "The was a good fight, Commander. It might give me time to clean my sword.\n\nAnd honor our fallen." }
WordHunterWoW_QuestEN[37307] = { title = "Gold Victory", description = "The stronger our enemies, the more soundly we must beat them. With so much at stake, a single weak blow could prove disastrous.\n\nLead us to great victory, Commander.", objectives = "The stronger our enemies, the more soundly we must beat them. With so much at stake, a single weak blow could prove disastrous.\n\nLead us to great victory, Commander.", progress = "The stronger our enemies, the more soundly we must beat them. With so much at stake, a single weak blow could prove disastrous.\n\nLead us to great victory, Commander.", completion = "A complete victory! Draenor denizens will mewl for weeks as they lick their wounds, in whatever dark places they live." }
