WordHunterWoW_QuestEN[37416] = { title = "Feast of the Spires", description = "Boss-mon, I prepared a great feast for you right over dere. You should be havin' a bite or two before you be goin' out for da day.\n\nTrust me, you will feel much betta if you do!", objectives = "Eat a Feast of the Spires at Axefall.Boss-mon, I prepared a great feast for you right over dere. You should be havin' a bite or two before you be goin' out for da day.\n\nTrust me, you will feel much betta if you do!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[37417] = { title = "Feast of the Spires", description = "Commander, I prepared a great feast for ye right over there. You should be have a bite o' two before you be go out fer the day.\n\nTrust me, it's good fer ya!", objectives = "Eat a Feast of the Spires at Southport.Commander, I prepared a great feast for ye right over there. You should be have a bite o' two before you be go out fer the day.\n\nTrust me, it's good fer ya!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[37418] = { title = "Fully Armed and Operational", description = "Commander! Great news! Now that the workshop is fully armed and operational, we can start cranking out siege weapons just as soon as we have the resources.\n\nThe Overcharged Demolisher is the pinnacle of goblin engineering, if I do say so myself. It's more powerful than your average demolisher, and you can use it almost anywhere! The only limit is the amount of fuel we're able to pack into the chasis.\n\nAs soon as you're ready to begin production, just bring us some resources and place a work order!", objectives = "Place a Work Order at your Garrison's Workshop.", completion = "Can't wait to get this thing up and running for you, commander!\n\nCheck back in tomorrow, and be sure to wear your blast goggles!" }
WordHunterWoW_QuestEN[37420] = { title = "Fully Armed and Operational", description = "Commander! Great news! Now that the workshop is fully armed and operational, we can start cranking out siege weapons just as soon as we have the resources.\n\nThe Overcharged Siege Engine is the pinnacle of gnomish  engineering, if I do say so myself. It's more powerful than your average siege engine and you can use it almost anywhere! The only limit is the amount of fuel we're able to pack into the chasis.\n\nAs soon as you're ready to begin production, just bring us some resources and place a work order!", objectives = "Place a Work Order at your Garrison's Workshop.", progress = "We're going to need resources if you want us to create a siege weapon!", completion = "Can't wait to get this thing up and running for you, commander!\n\nCheck back in tomorrow, and be sure to wear your blast goggles!" }
