WordHunterWoW_QuestEN[37483] = { title = "Captian's Whistle", description = "", objectives = "Bring Anne Dunworthy 100 Artifact Fragments for a Captian's Whistle.", progress = "We've brought our best here to help the fight for Ashran.\n\nBring me some of those Artifact Fragments and I'll give you a whistle to call a Captian to battle within the Road of Glory when you need them the most.", completion = "Good work. Use this whistle to call one of our very best to the battlefield when you need them the most." }
WordHunterWoW_QuestEN[37484] = { title = "Captain's Whistle", description = "", objectives = "Bring Anne Dunworthy 100 Artifact Fragments for a Captian's Whistle.", progress = "We've brought our best here to help the fight for Ashran.\n\nBring me some of those Artifact Fragments and I'll give you a whistle to call a Captian to battle within the Road of Glory when you need them the most.", completion = "Good work. Use this whistle to call one of our very best to the battlefield when you need them the most." }
WordHunterWoW_QuestEN[37485] = { title = "REUSE", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[37486] = { title = "Nar'thalas Still Suffers", description = "They have not forgiven me. I cannot blame them.\n\nPast crimes aside, I am still their prince. Even in death, I will do what I can to protect my people.\n\n{name}. Act as my champion. Find and defeat the creature that leads this naga attack against the people of Nar'thalas. After all these years, you - a {race} {class}, of all things - may be the instrument of my redemption.", objectives = "Defeat Athissa.", progress = "I will make it up to them. WE will make it up to them.", completion = "She spoke of the Tidestone? That sea witch must not realize how close she truly is to finding it.\n\nWe should move quickly. We are close to your prize, and the naga are circling in." }
WordHunterWoW_QuestEN[37492] = { title = "A Rather Long Walk", description = "I'm concerned for Elder Aldryth. He went out for a walk about ten thousand years ago, and he has not returned.\n\nWith these naga attacking, I fear he may be in danger!\n\nIf you dare venture out into the fray, do look out for our court elder.", objectives = "Find Elder Aldryth.", progress = "Have you seen him?", completion = "I can't tell you how relieved I am that Elder Aldryth has returned.\n\nHonestly, life here in the palace hasn't been the same without him. Everything seemed to have... lost its color. Perhaps now we can get back to our normal lives." }
WordHunterWoW_QuestEN[37493] = { title = "Vignette: Morphed Sentient", description = "", objectives = "" }
WordHunterWoW_QuestEN[37494] = { title = "Under Cover of Darkness", description = "We are off to Stormwind. Tethys will sneak us by water beneath the old barracks under cover of darkness tonight.\n\nThe rest will be up to you, Mathias, and myself. We will have to stealth through Stormwind and confront Detheroc at SI:7.\n\nAre you ready to do this, {name}?", objectives = "Speak with Taoshi when you're ready for Fleet Admiral Tethys to arrange your transport to Stormwind City.", completion = "We made it. Now all we have to do is get up there, sneak through my city -- which, mind you, is being watched by everyone -- then reveal and kill a dreadlord inside the headquarters of SI:7, Azeroth's most elite spy organization.\n\nPiece of cake. Ready to save the world, <name>?" }
WordHunterWoW_QuestEN[37495] = { title = "Plunder the Cove", description = "", objectives = "" }
WordHunterWoW_QuestEN[37496] = { title = "Infiltrating Shipwreck Arena", description = "The giants at Shipwreck Arena are very fond of smashing ships that sail too close to shore. They take the sailors prisoner and use them for their own amusement.\n\nI suppose it will be easy for you to infiltrate the place. It's breaking out that will be the difficult part.", objectives = "Infiltrate Shipwreck Arena and find Okuna Longtusk.", completion = "Did you get my bottle? Are you here to help us escape?" }
WordHunterWoW_QuestEN[37497] = { title = "Trailing the Tidestone", description = "Your quest for the Tidestone... it intrigues me. More than that, it suits my needs quite well. I have been in need of a champion for a very, very long time.\n\nIt is decided, then. I shall join you.\n\nWe will have to head east, through Nar'thalas.\n\nShall we depart?", objectives = "Escort Prince Farondis to the Ruins of Nar'thalas.", completion = "Perhaps this was a mistake." }
