WordHunterWoW_QuestEN[37507] = { title = "Boss Whalebelly's in Charge", description = "Great, let's get started! If we're going to break everyone out of here, you need to pose as a pit fighter like the rest of us. They won't just let you run around anywhere you want in here.\n\nFirst thing you need to do is present yourself to Boss Whalebelly. The giants may run this place, but as far as posing as one of us, Whalebelly's in charge.\n\nHe's speaking with his goons just to the south.", objectives = "Speak with Boss Whalebelly.", progress = "Go on. Go talk to him.", completion = "That could have gone better. Sounds like you've already made an enemy.\n\nStill, that'll work to our advantage. You versus Boss Whalebelly. The fight of the century... or at least, the day.\n\nNow to set everything up." }
WordHunterWoW_QuestEN[37508] = { title = "Tracking Event: Stacking the Deck", description = "", objectives = "" }
WordHunterWoW_QuestEN[37509] = { title = "Tracking Event: Stacking the Deck", description = "", objectives = "" }
WordHunterWoW_QuestEN[37510] = { title = "Sternfathom's Champion", description = "Since you defeated Ooker Dooker, there's a pit fighter spot open on Sternfathom's team. You should go establish yourself as his champion. That way, the giants won't think twice about why a stranger is suddenly coming and going as he pleases.\n\nMeanwhile, I'll start to sow some chaos so that we can strike at Prince Oceanus.", objectives = "Report to Sternfathom as his new pitfighter.", completion = "Hello, what can I do for you, little <race>?\n\nAhahaha... it's you!  I like how you came in and immediately confronted Whalebelly. That little tuskarr's got it coming.\n\nI can tell you're going to win big for me in the arena." }
WordHunterWoW_QuestEN[37511] = { title = "Dizzy Sparkshift", description = "I'm in a pretty good spot as far as artifacts go.\n\nWe have a couple other society members out in the field. I'd go look for them, but it seems like a bad idea from a health perspective.\n\nYou don't seem to have a problem with pain, think you could find Dizzy?", objectives = "Find Dizzy Sparkshift.", completion = "Shh... keep it down. The last thing I want is to get punched in the face by an ogre." }
WordHunterWoW_QuestEN[37512] = { title = "Primals Invasion! BETA", description = "The plants seem different today. Grass blades bend against the wind and catch on my boots. Twice this morning a tree branch struck my helmet as it fell.", objectives = "Repel the Primals invasion of your garrison.\n\n(Speak with Sergeant Crowler again to begin)" }
WordHunterWoW_QuestEN[37513] = { title = "Ogres Invasion! BETA", description = "Commander, our scouts say that Ogre bands march through the snow. If they want more battle after the beating we already delivered, then I'm eager to oblige them.", objectives = "Repel the Ogres invasion of your garrison.\n\n(Speak with Sergeant Grimjaw again to begin)" }
WordHunterWoW_QuestEN[37514] = { title = "Breakers Invasion!! BETA", description = "The earth quakes beneath us, Commander. Our scouts are not returning. I can feel an attack creeping up on us, but from where?", objectives = "Repel the Goren and Gronnling invasion of your garrison.\n\n(Speak with Sergeant Grimjaw again to begin)" }
WordHunterWoW_QuestEN[37515] = { title = "The Iron Horde Approaches... BETA", description = "There's smoke on the horizon... The Iron Horde is coming.", objectives = "Speak with Sergeant Crowler." }
WordHunterWoW_QuestEN[37516] = { title = "News for Nixxie", description = "Nixxie is probably worried sick about the potential loss of profits from this surveying operation.\n\nIf you see her can you let her know we will be back soonish?", objectives = "Speak with Nixxie.", completion = "It sounds like the excavation of Broken Precipice is going to be fully operational in no time.\n\nI can't wait to line my pockets with some of that sweet moolah." }
WordHunterWoW_QuestEN[37517] = { title = "News for Nixxie", description = "Nixxie is probably worried sick about the potential loss of profits from this surveying operation.\n\nIf you see her can you let her know we will be back soonish?", objectives = "Speak with Nixxie.", completion = "It sounds like the excavation of Broken Precipice is going to be fully operational in no time.\n\nI can't wait to line my pockets with some of that sweet moolah." }
WordHunterWoW_QuestEN[37518] = { title = "The Haunted Halls", description = "Now, what was it you wanted? You're here to see the Tidestone of Golganneth? Hah! Ho ho ha ha haa!\n\nHooo my.\n\nNo, only the academy's headmistress has the keys to that chamber, and she hasn't opened the door in... oh, I'd say about ten thousand years.\n\nYou'd best be off to class, now. Go on, then! Into the west wing with you!", objectives = "Enter the academy's west wing.", completion = "Yes, the headmistress is in her study, but I can't have you bothering her right now. Classes are about to start." }
WordHunterWoW_QuestEN[37520] = { title = "Vileclaw's Claw", description = "", objectives = "Vileclaw is feared throughout Nagrand as a vicious predator. While it is true that Vileclaw is one of the most dangerous raptors you'll ever encounter, she is also a savagely beautiful creature.\n\nVileclaw must be preserved for future generations to behold! If you can bring me back one of her vicious claws, I'll make sure you get a cut of the profit!", progress = "Vileclaw is feared throughout Nagrand as a vicious predator. While it is true that Vileclaw is one of the most dangerous raptors you'll ever encounter, she is also a savagely beautiful creature.\n\nVileclaw must be preserved for future generations to behold! If you can bring me back one of her vicious claws, I'll make sure you get a cut of the profit!", completion = "Nice work, <name>!\n\nIt's times like these that make me proud to be your mentor. You'll make a fine archaeologist someday!\n\nHere's your cut!" }
WordHunterWoW_QuestEN[37523] = { title = "Assault on the Gorian Proving Grounds", description = "The ogres at the Gorian Proving Grounds are rousing champions to turn against our forces in Nagrand.\n\nA decisive assault on their training grounds should prevent them from mustering the forces they need to stand against us, and will help remind them that we are not an enemy they want to make.", objectives = "Assault the ogre forces at the Gorian Proving Grounds in Nagrand." }
WordHunterWoW_QuestEN[37524] = { title = "Assault on the Gorian Proving Grounds", description = "The ogres at the Gorian Proving Grounds be rousin' champions to turn against our forces in Nagrand.\n\nA decisive assault on their training grounds should prevent dem from musterin' the forces dey be needin' to stand against us, and will help remind them that we are not an enemy they want to be makin'.", objectives = "Assault the ogre forces at the Gorian Proving Grounds in Nagrand." }
WordHunterWoW_QuestEN[37525] = { title = "Vignette: Ak'ox the Slaughterer", description = "", objectives = "" }
WordHunterWoW_QuestEN[37526] = { title = "Farondis Murder Flag", description = "", objectives = "" }
WordHunterWoW_QuestEN[37528] = { title = "Let Sleeping Giants Lie", description = "We're going to need a diversion to get close to Prince Oceanus. Are you thinking what I'm thinking?\n\nSee Sleepy Dhow over there? He's guarding all of the weapons the giants take from our shipwrecks. We can use those weapons to arm the rest of the pit fighters that are held in the caves.\n\nAll you have to do is get past that giant without waking him.", objectives = "Collect the Giants' Stash of Weapons.", progress = "As soon as I can, I'll arm the gladiators in Oceanus Cove.", completion = "I couldn't have snuck past him better. Now, to get these weapons into the right hands." }
WordHunterWoW_QuestEN[37530] = { title = "Save Yourself", description = "Of course I couldn't sit back and let them just cart you away.\n\nI will explain everything.", objectives = "Speak with Farondis and hear his account of how he saved you.", progress = "Let me show you what happened.", completion = "What happened, Farondis?" }
WordHunterWoW_QuestEN[37531] = { title = "Tracking - See Closed Chest", description = "", objectives = "" }
WordHunterWoW_QuestEN[37536] = { title = "Morale Booster", description = "Things may look good from where you're standing, but, we're losing. However, do not fret, my little {race} friend. You can help.\n\nListen closely. Ooka Dooker, Ooker's sister, is back over yonder in the champions' cave making her world famous Fighter Chow. It'll do the trick and boost our team's morale.\n\nAll you have to do is to convince her to hand it over.", objectives = "Get the Fighter Chow from Ooka Dooker", completion = "Yes, this'll do nicely... oh no! The last of my pit fighters have been defeated.\n\nIt's just you and me now, little <race>." }
WordHunterWoW_QuestEN[37537] = { title = "Ravyn-Drath", description = "", objectives = "" }
WordHunterWoW_QuestEN[37538] = { title = "Round 1, Fight!", description = "All of my gladiators are out of commission!\n\nIt's down to you, {name}. Bilgerudder's going to pit his three champions against you.", objectives = "Have Sternfathom throw you into the arena, defeat Boss Whalebelly, and then find Okuna Longtusk inside Oceanus Cove.", completion = "<This is where you expected to find Okuna. Instead, you only found the pack with the weapons.>" }
WordHunterWoW_QuestEN[37539] = { title = "UNUSED", description = "", objectives = "" }
WordHunterWoW_QuestEN[37540] = { title = "Essence of the Iron Conqueror", description = "Redeem your Essence of the Iron Conqueror with Lady Liadrin to select an armament of your choice.", objectives = "Collect an Essence of the Iron Conqueror.", progress = "Well met, <class>. I see you have a claimed a trophy in your recent battles.", completion = "<name>, your courage and dedication has made Draenor a safer place. Take these armaments and go in the Light." }
WordHunterWoW_QuestEN[37541] = { title = "Essence of the Iron Vanquisher", description = "Redeem your Essence of the Iron Vanquisher with Lady Liadrin to select an armament of your choice.", objectives = "Obtain an Essence of the Iron Vanquisher.", progress = "Well met, <class>. I see you have a claimed a trophy in your recent battles.", completion = "<name>, your courage and dedication has made Draenor a safer place. Take these armaments and go in the Light." }
WordHunterWoW_QuestEN[37542] = { title = "No Time for Tryouts", description = "We don't have time for you to go through a lengthy set of tryouts. But, fighting in the arena is our best chance at getting you in good with the giants.\n\nThat kind-hearted giant over there that's losing against Bilgerudder is Sternfathom. If you were to defeat his hozen champion, you'd make yourself a spot on his team.\n\nLooks like Ooker Dooker's taking a rest between bouts. Now's the time to deliver a good ol' monkey beatdown.", objectives = "Deliver a beatdown to Ooker Dooker.", progress = "By giving that hozen a good beating, you'll be making a spot for yourself in the arena.\n\nYou don't have to kill him, though.", completion = "You made quick work of that monkey. Now there's an empty position on Sternfathom's team that you can fill.\n\nBut first, let's get me set up for what comes after your big match." }
