WordHunterWoW_QuestEN[37563] = { title = "The Frostwolves Stand Ready", description = "Though we have lost much this day, the Frostwolves stand ready to uphold our pact with your people.\n\nTo honor this agreement, some of my clan have asked to join your ranks and fight alongside your forces.\n\nOur numbers are strained so I ask that you chose only one.\n\nSpeak with me when you have made your decision.", objectives = "Choose a follower (either Greatmother Geyah, Kal'gor the Honorable, or Lokra) and then speak with Makar Stonebinder.", progress = "Have you decided which orc to take with you?", completion = "Excellent choice. I will be sad to see them leave, but I know they will help strengthen our combined packs in the coming conflicts.\n\nI will see that they make their way to your garrison as soon as they have said farewell to their loved ones.\n\nThey should be ready the next time you need to send followers on a mission." }
WordHunterWoW_QuestEN[37564] = { title = "Your First Blacksmithing Work Order", description = "Now that the forge is complete, we can start producing truesteel ingots for you. When you have the ingredients, please speak with my assistant to start the first work order.You will receive:", objectives = "Start and collect your first Blacksmithing work order at the Forge." }
WordHunterWoW_QuestEN[37565] = { title = "The Right Weapon for the Job", description = "<You and Okuna were going to arm the captives in here. The idea was to free them and cause as much chaos as possible. It's the only sure way to be able to get close to the prince.\n\nYou still have the weapons. You're just going to have to be careful sneaking around the giants.>", objectives = "Arm 25 Shipwrecked Captives.", completion = "Now the captives are free. Thank you, <name>.\n\nReady for the prince?" }
WordHunterWoW_QuestEN[37566] = { title = "The Prince is Going Down", description = "{name}! I knew you'd come.\n\nQuick, let me out of here and we'll take this giant down.", objectives = "Free Okuna Longtusk and kill Prince Oceanus.", completion = "With Oceanus dead, the skrogs will start fighting amongst themselves. They'll certainly be too busy to provide any further assistance to the naga.\n\nI'd say this was a job well done, despite my being captured. Good thing you came along.\n\nI'll see you around, <name>." }
WordHunterWoW_QuestEN[37567] = { title = "Interact with Dudebro", description = "", objectives = "" }
WordHunterWoW_QuestEN[37568] = { title = "Your First Alchemy Work Order", description = "Now that the alchemy lab is complete, we can start producing alchemical catalysts for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "Start and collect your first Alchemy work order at the Alchemy Lab.", progress = "Yes?", completion = "Let me unpack that for you.\n\nI should let you know - while we managed to expedite this one, future work orders will take longer." }
