WordHunterWoW_QuestEN[37627] = { title = "Assault on the Broken Precipice", description = "[PH]Commander! You just missed a group of rangari with some disturbing news. The Shadowmoon Orcs have been spotted in the hills above Anguish Fortress. The scouts reported seeing strange rituals and beings of pure darkness. Those orcs must be up there trying to summon more minions from the Void!\n\nIf we do not intervene all we have gained in Shadowmoon Valley might be lost!You will receive:", objectives = "Take out as many Shadowmoon orcs and their Void minions as you can." }
