WordHunterWoW_QuestEN[37687] = { title = "Garrison Campaign: In the Shadows", description = "I need your help. Iskar has gone missing. I have reason to believe he has followed the remnants of the Sethekk who have been gathering here in Tanaan. I've been investigating and... what was that?\n\n<Reshad's voice drops to a whisper>\n\nThere is movement in the shadows, we are being watched!\n\nTake these vials, they form a gas with a terrible smell when the liquid comes in contact with the air. Smells terrible, they won't be able to resist it. Use them to drive our watchers out of hiding.", objectives = "Kill 3 Council Nightblades within Lion's Watch.", completion = "So the Shadow Council is involved? Interesting..." }
WordHunterWoW_QuestEN[37688] = { title = "Garrison Campaign: In the Shadows", description = "I need your help. Iskar has gone missing. I have reason to believe he has followed the remnants of the Sethekk who have been gathering here in Tanaan. I've been investigating and... what was that?\n\n<Reshad's voice drops to a whisper>\n\nThere is movement in the shadows, we are being watched!\n\nTake these vials, they form a gas with a terrible smell when the liquid comes in contact with the air. Smells terrible, they won't be able to resist it. Use them to drive our watchers out of hiding.", objectives = "Kill 3 Council Nightblades within Vol'mar.", progress = "Did you take care of our watchers?", completion = "So the Shadow Council is involved? Interesting..." }
WordHunterWoW_QuestEN[37689] = { title = "The Imposter", description = "Detheroc has SI:7's finest snipers on all of the rooftops. We can't mount up and we can't fly. There are grapple points above so that we can move up the cliff. \n\nWe've also setup hay bales to hide in along the likely routes to SI:7. We just need to stealth in and kill Detheroc.\n\nOnce we get up there, we'll separate to increase the chances of at least one of us making it through the city.\n\nGood luck, {name}.", objectives = "Grapple up the Lion's Rest cliffs, sneak through Stormwind City to the SI:7 courtyard, and then kill Detheroc.", completion = "You did it! Mathias Shaw is back in charge of SI:7 and you prevented an all-out war between the Alliance and Horde.\n\nThe rest of us agree, you've proven yourself an invaluable member of the Council of Shadows and the Uncrowned.\n\nCongratulations, Shadowblade <name>!" }
WordHunterWoW_QuestEN[37690] = { title = "Those Who Remember", description = "The ghostly elves, to the south, once had the Pillar of Creation known as the Tidestone of Golganneth.\n\nTheir great city of Nar'thalas was destroyed an eon ago. The city's ruler, Prince Farondis, fell with the city. You small ones die so easily.\n\nIf anyone knows where the fragments rest, it will be the ghost of the prince. Seek out his people.", objectives = "Locate Nightwatcher Idri in the Drowned Gardens.", completion = "Who goes there?\n\nAre you an emissary from that bizarre floating city?" }
WordHunterWoW_QuestEN[37691] = { title = "he Ancient One", description = "This place is now the home of what is left of the Blue Dragonflight. Its eldest dragon, Senegos, lies ahead within a pool of ley energy. If any are wise enough to help us find the Pillar of Creation that we seek on Azsuna, it will be him.\n\nStellagosa went ahead to join her grandfather. She assured me that we are welcome to enter the repose.\n\nCome, <name>, we must hurry. Even from here, I can sense his life force waning. Let us approach him together.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Approach Senegos." }
WordHunterWoW_QuestEN[37697] = { title = "Treasure Goblin", description = "", objectives = "" }
WordHunterWoW_QuestEN[37713] = { title = "Azsuna - Treasure 002 - El'dranil Tablet", description = "", objectives = "" }
WordHunterWoW_QuestEN[37726] = { title = "Valiyaka the Stormbringer", description = "", objectives = "" }
WordHunterWoW_QuestEN[37727] = { title = "The Magister of Mixology", description = "As you must know, I'm a connoisseur of drinks... specifically, arcane-infused spirits. Cocktail mixing is alchemy, and as everyone knows, alchemy is magic.\n\nMy latest drink must be more exotic than anything I've conjured before. I already have most of what I need. But there are a couple of items left on the list.\n\nNotice the herons down in the lagoon? As with many of the creatures on Azsuna, the magic coursing through the island permeates them.\n\nTheir eggs will do nicely.", objectives = "Collect 6 Arcane-Infused Eggs.", progress = "Are we speaking again because you have my eggs?", completion = "Capital! A prodigious start.\n\nI implore you to create this marvelous mixture for yourself. I want to share the delight of alchemical spirits with the world!\n\nYou'll need to get more eggs for yourself, though." }
WordHunterWoW_QuestEN[37728] = { title = "Presentation is Everything", description = "The eggs will provide the 'oomph' to my drink's character. But there's another element, and this must not be underestimated!\n\nPresentation.\n\nNow, you could go with your standard olive skewered on a toothpick. Maybe a carrot stalk stuck slapdash out of a glass.\n\nBut then, you wouldn't be me.\n\nNo, my friend. What MY drink needs to sell it visually comes from a one-of-a-kind creature. I'm only going to serve it once and so my drink deserves something unique.\n\nThe eyes of Gangamesh are what I need.", objectives = "Collect the Six Eyes of Gangamesh.", progress = "Yes? You have the eyes?", completion = "I was going to present this to one of the ladies of the court. Doing so might increase my standing in certain social circles.\n\nBut, I just can't bring myself to do it. Who better to drink my latest masterpiece than, well... me?" }
WordHunterWoW_QuestEN[37729] = { title = "Pop Quiz: Advanced Rune Drawing", description = "Still aching to get into the headmistress' study, eh? I suppose I can let you in... as long as you prove that you've been studying.\n\nProper rune formation is essential when it comes to spellcasting. If you can draw a rune, you can cast a spell.\n\nI will provide outlines for you. You can simply use your feet to trace the runes.", objectives = "Trace an arcane rune, a fire rune, and a frost rune.", progress = "Go on, then! Get those feet moving!", completion = "Exemplary work, young <name>. With runes like these, you'll be graduating in no time." }
WordHunterWoW_QuestEN[37730] = { title = "The Headmistress' Keys", description = "I have a suspicion you are avoiding your studies - but I can see you're anxious to see the Headmistress.\n\nVery well! Headmistress Azuremoon can be found up ahead, though I doubt she will enjoy being interrupted.", objectives = "Obtain the Tidestone Vault Key from Elya Azuremoon, the Academy Headmistress.", progress = "Were you able to meet with the headmistress?", completion = "She... she gave you her key? My word!" }
WordHunterWoW_QuestEN[37733] = { title = "Prince Farondis", description = "I'm glad to see that my doubts in you were unfounded.\n\nYou seek Prince Farondis? Follow me. I will show you to the prince's hall.", objectives = "Meet up with Nightwatcher Idri at the Crumbled Palace.", completion = "That's him, behind me." }
WordHunterWoW_QuestEN[37736] = { title = "Dressing With Class", description = "Now stop right there. Look at you! You look like you just walked in off of the street. Where are your robes and hat?\n\nAnd don't tell me you've entered the academy without your wand and spellbook.\n\nFreshmen.\n\nPut yourself together, and maybe then I will consider letting you enter the academy.", objectives = "Obtain a Nar'thalas Academy Hat, Robes, Wand, and Spellbook.", progress = "Still trying to get into the academy, I see.", completion = "Your hat and robes don't match, but you still look better. I hardly recognize you." }
WordHunterWoW_QuestEN[37749] = { title = "Trials of Khadgar: Iron Maidens", description = "Defeat your enemies with greater skill to earn the favor of Khadgar - and with it, greater rewards!", objectives = "Defeat the Iron Maidens encounter, with the following conditions." }
