WordHunterWoW_QuestEN[37988] = { title = "Art Tracker - Ashbringer - Tier 2 - Holy", description = "", objectives = "" }
WordHunterWoW_QuestEN[37989] = { title = "Syphonus", description = "", objectives = "" }
WordHunterWoW_QuestEN[37990] = { title = "Vignette: Cindral", description = "", objectives = "" }
WordHunterWoW_QuestEN[37991] = { title = "Agapanthus", description = "<This whelpling is trying to get your attention. She locks eyes with you, then quickly flicks her head toward the northeast.>", objectives = "Investigate and assist the visitors in Azurewing Repose.", completion = "Hail, <class>. We could use your aid." }
WordHunterWoW_QuestEN[37992] = { title = "Gutrek's Cleaver: The Spirit Forge", description = "With the pieces recovered, all that is left is to reforge Gutrek's Cleaver. Goldspade's journal seems to indicate that the only place to do this is the location where it was initially dismantled.\n\nThe journal mentions a \"Spirit Forge\" used to dismantle the blade, and that it may be located somewhere in the nearby gorge. Find the forge and use it to combine the pieces you've gathered.", objectives = "Locate the Spirit Forge in Earthshaker Gorge and reforge Gutrek's Cleaver.", progress = "Dis be da blade dat Jones was lookin for?", completion = "Excellent, mon! I be takin dis to Jones right away. \n\nHere be your reward." }
WordHunterWoW_QuestEN[37993] = { title = "Amulet of Rukhmar: The Apexis Device", description = "Now that the keys have been activated, the Apexis device that leads to the amulet should be accessible. \n\nThe Arakkoa research states that it is likely located in Lost Veil Anzu, within the \"shrine to the raven god.\"", objectives = "Activate the Apexis device and claim the Amulet of Rukhmar.", progress = "Ya manage ta get da amulet?", completion = "It's good we got dis and not da arakkoa.\n\nJones will be wantin dis, I'm sure." }
WordHunterWoW_QuestEN[37994] = { title = "Dark Grimoire: Breaching the Barrier", description = "The components have been gathered and the \"Arcane Bunker Buster\" is assembled. Hopefully, this should pack enough punch to take out the barrier.\n\nThere's only one way to find out...", objectives = "Destroy the ancient barrier below Socrethar's Rise and claim the Grimoire of the Nameless Void.", progress = "I can sense a bad voodoo comin from ya, mon. \n\nDat be da book I'm feelin?", completion = "Dis book be a bad ting, mon. I'm glad we got it before it came into da wrong hands. \n\nI'll get it ta Jones for ya." }
WordHunterWoW_QuestEN[37995] = { title = "Gronnsbane: The Blessing of Beasts", description = "Gronnsbane now pulses with energies of fire and frost. All that remains to restore the full power of the weapon is to receive the Blessing of the Beast. Argoram believed this could be accomplished by bloodying the weapon against one of the ancient black rylaks of Stonefury Cliffs. His journal reads:\n\n\"High in the Stonefury Cliffs, I have seen an altar where the ogres have left offerings to these ancient beasts. Perhaps I could use it to lure one of them\"", objectives = "Defeat the ancient black rylak and douse Gronnsbane in its blood.\n\nOnce empowered, return the weapon to Rokhan for your reward.", progress = "You bring da spear from da Thunderlords?", completion = "Jones will be happy when he sees dis. \n\nHere's da payment he promised." }
WordHunterWoW_QuestEN[37996] = { title = "The Silent Skull: Taking from the Taker", description = "With the reagents found, you should seek out Grinning Tolg's camp in the nearby cave to brew the elixir. \n\nOnce the elixir is consumed, you should be able to communicate with the ravagers there. With any luck, they should be able to bring you to Skulltaker.\n\nHis mask should bring a hefty reward.", objectives = "Use the Laughing Skull elixir to find Skulltaker and claim the Silent Skull.", progress = "Dat must be da cursed skull you got dere.", completion = "Dis be an odd mask for a Laughing Skull, to be sure. \n\nJones left dis reward for ya." }
WordHunterWoW_QuestEN[37997] = { title = "Dream of Argus: The Crystal Reborn", description = "With the shards recovered, it is now possible to restore the Dream of Argus. You must seek out the device that Maatun mentions in his journal, which is said to be in a cave overlooking Anguish Fortress.", objectives = "Locate the crystal reconstruction device and use it to restore the Dream of Argus.", progress = "You get da crystal put back togetha?", completion = "Astoundin, mon! I'd a never been able ta tell dis was eva broken. \n\nHere's da reward dat Jones left, I'll get dis to im." }
WordHunterWoW_QuestEN[38000] = { title = "Azsuna - Treasure 001 - Drowned Ruins", description = "", objectives = "" }
WordHunterWoW_QuestEN[38001] = { title = "Commander in the Field!", description = "We have been stopped by these new fel orcs, but we will ultimately prevail. Draka and I did manage to get a full scouting group out into the jungle to gather what else we will have to deal with.\n\nYou should seek them out, gain a full understanding of what we face here.", objectives = "Get reports from various scouts in Tanaan Jungle.", completion = "We have quite a war on our hands. At least we do not lack for targets to strike!" }
WordHunterWoW_QuestEN[38003] = { title = "Vignette: Killed Gaiju", description = "", objectives = "" }
WordHunterWoW_QuestEN[38004] = { title = "Vignette: Looted Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[38005] = { title = "delete me", description = "", objectives = "" }
WordHunterWoW_QuestEN[38006] = { title = "delete me", description = "", objectives = "" }
WordHunterWoW_QuestEN[38007] = { title = "zzOldEMPTY TEST", description = "", objectives = "" }
WordHunterWoW_QuestEN[38008] = { title = "The Road of Glory", description = "The Horde intends to force us out of Ashran, <name>. We can't let them succeed. March into the Road of Glory and thin their ranks by at least five.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Chris Clarkie in Stormshield wants you to kill 5 members of the Horde within the Road of Glory." }
WordHunterWoW_QuestEN[38009] = { title = "Assault on the Ruins of Kra'nak", description = "", objectives = "" }
WordHunterWoW_QuestEN[38010] = { title = "Max-level Choice Tracker: Tanaan 6.2 - Ruins of Kra'nak", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[38014] = { title = "Feasting on the Dragon", description = "You killed their leader, so they came here? Understandable. These creatures crave only one thing - magic - and they can sniff it out from leagues away.\n\nWithout a leader, they will soon wither and die. Our only recourse in the meantime is to put as many as possible down before they take these dragons with them!", objectives = "Slay 15 withered in Azurewing Repose.", progress = "Yes, <name>?", completion = "That will have to do for now." }
WordHunterWoW_QuestEN[38015] = { title = "On the Brink", description = "This many withered threaten to wipe our brood out completely!\n\nQuickly, {name}! Crack off a ley crystal and heal any wounded drakes you can find out on the battlefield.\n\nI will do what I can to keep these whelplings safe and healthy.", objectives = "Use the Radiant Ley Crystal or your healing spells and abilities to resuscitate wounded dragons.", progress = "Hurry, <name>!", completion = "Well done. I saw the other drakes take to the skies.\n\nAnd look! You found Emmigosa!\n\nIt seems she's taken a shine to you, <name>. I trust you'll keep her safe for now." }
WordHunterWoW_QuestEN[38017] = { title = "Razing Your Rivals", description = "Who are you but another grain of sand on an endless beach of challengers?\n\nAlthough my body may be gone, my watch over this vault has not yet ended.\n\nDare you enter before proving your might to me?", objectives = "" }
WordHunterWoW_QuestEN[38019] = { title = "Yotnar's Eye", description = "Who is it that stands before me?\n\nSkovald destroyed my body. Soon after a bird stole my right eye, a shiny treasure for its nests... Who am I without my eyes? How can I judge those that wish to pass without my sight? I grow weary...\n\nPerhaps you could use some stones to knock those nests out of the trees? Find my eye and we can discuss the trials in further detail.\n\n<You pick up handful of stones next to Yotnar's head.>", objectives = "" }
WordHunterWoW_QuestEN[38020] = { title = "Assault on the Temple of Sha'naar", description = "", objectives = "" }
WordHunterWoW_QuestEN[38021] = { title = "Max-level Choice Tracker: Tanaan 6.2 - Temple of Sha'naar", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[38022] = { title = "ssault on the Temple of Sha'naar", description = "The Sargerei council continues to work in secret with the warlock, Gul'dan. Up in the hills of Tanaan Jungle, they have converted a once-sacred temple into a den of demonic summoning.\n\nWe must attack them now, before their rituals complete. The longer we delay, the stronger their forces become.You will receive:", objectives = "Assault the Sargerei forces at the Temple of Sha'naar in Tanaan Jungle." }
WordHunterWoW_QuestEN[38026] = { title = "Vignette: Imp-Master Valessa", description = "", objectives = "" }
WordHunterWoW_QuestEN[38028] = { title = "Vignette: High Priest Ikzan", description = "", objectives = "" }
WordHunterWoW_QuestEN[38029] = { title = "Vignette: Lady Oran", description = "", objectives = "" }
WordHunterWoW_QuestEN[38030] = { title = "Vignette: Houndmaster Jax'zor", description = "", objectives = "" }
WordHunterWoW_QuestEN[38031] = { title = "Vignette: Ceraxas", description = "", objectives = "" }
WordHunterWoW_QuestEN[38032] = { title = "Vignette: Mistress Thavra", description = "", objectives = "" }
WordHunterWoW_QuestEN[38034] = { title = "Vignette: Rasthe", description = "", objectives = "" }
WordHunterWoW_QuestEN[38035] = { title = "A Royal Summons", description = "Well met, {name}. I have come on behalf of King Anduin Wrynn.\n\nMy crew is preparing for a special mission, and the king would like you to join us. Please review this official summons and, if you are satisfied, return with me to Stormwind Harbor.\n\n<Rogers hands you a sealed envelope.>", objectives = "Use the Royal Summons and follow Sky Admiral Rogers through the portal to Stormwind Harbor.", progress = "Can we count on you?", completion = "Thank you for your cooperation." }
WordHunterWoW_QuestEN[38036] = { title = "Supplies From the Skies", description = "Are you feeling alright? Say 'ah.'\n\n<Mishka attempts to depress your tongue with a damp twig.>\n\nSorry... we are in desperate need of medical supplies here. The infirmary on the Skyfire was well-stocked, but it's all scattered to the winds now.\n\nAnything you can salvage from the wreck will save lives!", objectives = "Gather 5 Skyfire First Aid Kits.", progress = "Did you find anything?", completion = "Just in time! I was about to start bandaging wounds with leaves." }
WordHunterWoW_QuestEN[38037] = { title = "Cache of Infernals", description = "", objectives = "" }
