WordHunterWoW_QuestEN[38043] = { title = "Bleeding the Bleeding Hollow", description = "", objectives = "" }
WordHunterWoW_QuestEN[38044] = { title = "Bleeding the Bleeding Hollow", description = "The Bleeding Hollow provide significant reinforcement to the Iron Horde in Tanaan. From their home in Zeth'Gol they relentlessly pursue our scouts, disrupt our operations, and gather more power for Gul'dan's magic.\n\nWe should consider a direct raid on Zeth'Gol to make them pull back their forces across the valley. This should give us some breathing room... for a time.", objectives = "Assault the Bleeding Hollow at Zeth'Gol in Tanaan Jungle.", progress = "Have you completed the raid, general?", completion = "I already have reports of Bleeding Hollow hunters falling back to Zeth'Gol. This will give us a good edge in the battles to come." }
WordHunterWoW_QuestEN[38045] = { title = "Bleeding the Bleeding Hollow", description = "The Bleeding Hollow provide significant reinforcement to the Iron Horde in Tanaan. From their home in Zeth'Gol they relentlessly pursue our scouts, disrupt our operations, and gather more power for Gul'dan's magic.\n\nWe should consider a direct raid on Zeth'Gol to make them pull back their forces across the valley. This should give us some breathing room... for a time.", objectives = "Assault the Bleeding Hollow at Zeth'Gol in Tanaan Jungle.", progress = "Have you completed the raid yet, general?", completion = "Well done, commander! The Bleeding Hollow are sending their best warriors back to Zeth'Gol to defend it.\n\nThis should give us an advantage, albeit temporarily." }
WordHunterWoW_QuestEN[38046] = { title = "Battle At The Iron Front", description = "General, our troops are currently engaged in a conjoined assault at the Iron Front. The fight has been raging for some time now, and casualties are high.\n\nReport to the Iron Front and lend your strength to the war effort. I have no doubt that your presence on the battlefield will inspire the soldiers to victory!", objectives = "Aid the Alliance and Horde assault at The Iron Front in Tanaan Jungle.", completion = "I'm already hearing reports from The Iron Front that the tide of the battle has turned.\n\nSoon, The Iron Horde will have nowhere to run!" }
WordHunterWoW_QuestEN[38047] = { title = "Battle At The Iron Front", description = "The war against the Iron horde rages on.\n\nNot far from here at The Iron Front, our warriors are engaged in mortal combat with the enemy. They fight tenaciously and with great fury, but the losses have been severe.\n\nGo to The Iron Front and show the enemy that we will not falter in this war.\n\nShow them that we fight as wolves!", objectives = "Aid the Alliance and Horde assault at The Iron Front in Tanaan Jungle.", completion = "Thanks to your aid, we have gained a foothold at The Iron Front. Soon, Gul'dan and the Iron Horde will have nowhere else to run." }
WordHunterWoW_QuestEN[38051] = { title = "Battle At The Iron Front", description = "", objectives = "" }
WordHunterWoW_QuestEN[38052] = { title = "Boarded!", description = "Glad to see you survived the crash. Unfortunately, so did most of the enemy's boarding party.\n\nJust the thought of those monsters setting foot on my ship makes me sick. Wipe them out, {name}. For my crew... For King Wrynn...\n\nFor the Alliance!", objectives = "Slay 8 Forsaken Bat-Riders or Forsaken Deathstalkers.", progress = "There will be no peace with those monsters running free.", completion = "Don't worry about the ship - it's just wood and metal.\n\nThe Skyfire lives on as long as we keep fighting." }
WordHunterWoW_QuestEN[38053] = { title = "Assault and Battery", description = "We need to report our position to the Alliance navy ASAP!\n\nI am building a new transponder to send a distress signal, but I need a battery from the Skyfire's communications console.\n\nYou'll find the console at the top of the ship - I just hope those undead haven't put their creepy, bony fingers on it yet!", objectives = "Recover the Transponder Battery from Dread-Rider Malwick.", progress = "I cannot build a new transponder without that battery!", completion = "NUTS and BOLTS!\n\nPardon my language.\n\nThis thing is almost as dead as the guy you took it from. We need juice, and lots of it. I have an idea..." }
WordHunterWoW_QuestEN[38054] = { title = "Battle At The Iron Front", description = "", objectives = "" }
WordHunterWoW_QuestEN[38057] = { title = "The Lost Legion", description = "The heroic men and women of the 7th Legion stayed at the front of the ship to fight off storm drakes while the crew evacuated.\n\nNone of them have returned.\n\nPlease find them, {name}!", objectives = "Locate the missing 7th Legion Dragoons.", completion = "<Though his eyes are open, the soldier does not respond to your presence. An electrical field buzzes around him.>" }
WordHunterWoW_QuestEN[38058] = { title = "Lightning Rod", description = "<Overspark's tiny hands move like lightning, affixing coils and tubes to the device before cramming it into a parachute pack.>\n\nPut this on.\n\nJust up the hill you'll find the front half of the Skyfire - and the big nest of storm drakes it crashed into! We can use the energy from those drakes to charge the transponder.\n\nYou'll have to incite them, of course, but the device should draw most of the power.\n\nThe probability of you being electrocuted is well within acceptable parameters!", objectives = "Charge the Transponder by absorbing Storm Drake lightning attacks." }
WordHunterWoW_QuestEN[38059] = { title = "Pins and Needles", description = "Hngghh!\n\nNope, can't stand yet. It's all pins and needles.\n\nSmall fries like this are usually no problem for the 7th, but we weren't prepared for their electrical attacks. Before I knew it, I was trapped in some kind of static field. Couldn't move a muscle until you came along.\n\nMy comrades were carried deeper into the cave. Get 'em out before they become whelp chow!", objectives = "Release 6 7th Legion Dragoons from static fields." }
WordHunterWoW_QuestEN[38060] = { title = "Signal Boost", description = "The Skyfire's starboard propeller came to rest on the cliffs overlooking our camp - we're gonna use it like a big antenna and push our distress signal so far that even Mekkatorque's alarm clock could pick it up!\n\nUnfortunately, it might attract some unwanted attention.\n\nWe're braced for enemy contact down here at the camp - fire up that signal and be ready to defend the antenna!", objectives = "Use the Skyfire Propeller to broadcast a distress signal, then hold out until help arrives.", completion = "The distress signal got through. We'll be evacuated to Greywatch immediately.\n\nI'm afraid that, for now, you will have to continue on your mission without us. Once we are settled, I will send out recon patrols to see if we can glean the location of the Aegis.\n\nYou must secure the Aegis of Aggramar if we are to drive back the Legion threat!" }
WordHunterWoW_QuestEN[38061] = { title = "Pridelord Meowl", description = "", objectives = "" }
WordHunterWoW_QuestEN[38062] = { title = "Yotnar's Blessing", description = "Skovald is in league with legion. He killed my brother Rudiaus and scattered his parts.\n\nRudiaus' corpse has been reanimated... a plaything for the Skovald's minions. That was the last thing I saw before an imp stole my eye and possessed my pet Aetoz. I heard Skovald order his demons to bury the remains of Rudiaus, denying challengers access to the vault.\n\nSkovald underestimates the gods. Bring me my eye and any remains of my brother you find. Complete this task and your trials will begin.", objectives = "" }
