WordHunterWoW_QuestEN[38142] = { title = "Archdruid of the Claw", description = "Near the southern edge of our forest you will find Sleeper's Barrow.\n\nThere, Archdruid Koda Steelclaw and her dedicated disciples carry out their sacred duty to observe the Emerald Dream.\n\nFind disciple Rylissa Bearsong in Steelclaw Vale and notify her of the crisis in the Grove of Cenarius.", objectives = "Locate Steelclaw Vale.", completion = "The forest already whispers of Malfurion's return. There are few among us who have not heard of his deeds.\n\nThe trees said he also travels with a companion, one named <name>. Are you he?" }
WordHunterWoW_QuestEN[38143] = { title = "Awakening the Archdruid", description = "Now, we must focus our efforts on waking Archdruid Steelclaw.\n\nShe and our druid brethren slumber in the barrow dens to the south.\n\nWith the furbolgs quelled, we can pass safely to the entrance.\n\nGo and awaken the Archdruid. I pray to Elune that we are not too late.", objectives = "Awaken the Archdruid of the Claw.", completion = "<The Archdruid's deep, shallow breaths rumble across the chamber.>" }
WordHunterWoW_QuestEN[38144] = { title = "The Demons Below", description = "Something, someone, intended us to never awaken. I sense their presence is still here in the barrow.\n\n<Koda takes a moment to stand.>\n\nMy body is weak from deep slumber.\n\nIf you would aid us, clear our barrow of any enemies.", objectives = "Kill 8 Darkfiend Intruders.", progress = "This was no accident. Someone intended us to sleep forever.", completion = "Excellent. The chambers are clear. Very impressive, <class>." }
WordHunterWoW_QuestEN[38145] = { title = "Out of the Dream", description = "Malfurion Stormrage... A name I have not heard in centuries.\n\nHe was teacher to many of us. If he seeks my audience, I cannot refuse.\n\nI will go to the Grove of Cenarius, but first, we must awaken the rest of my clan. They slumber with no way of waking.\n\nA mysterious force of great power is at work against us.\n\nI am still too weak from my hibernation. Please, stranger, go and free them from their dreams.", objectives = "Awaken 8 Druids of the Claw.", progress = "The Druids of the Claw must awaken. We are needed.", completion = "Well done, hero. With my brethren at my side, we will be ready to aid Malfurion." }
WordHunterWoW_QuestEN[38146] = { title = "The Chieftain's Beads", description = "The ceremonial beads, decorated with shells and feathers, are worn by the clan's chieftain.\n\nPerhaps Elder Sookh would be interested in seeing these.", objectives = "Speak to Elder Sookh at Smolderhide Thicket.", completion = "Graw was the first to succumb to the madness, and the rest of the clan followed.\n\nWith these, I will take the reins as our clan's new chieftain.\n\nThank you, traveler. I will do my best to rebuild my clan." }
WordHunterWoW_QuestEN[38147] = { title = "Entangled Dreams", description = "I sense powerful magic emanating from deep within the barrow.\n\nWhatever is down there weaves a powerful spell, entangling us within our dreams.\n\nI am still too weak, but your skills are quite impressive, hero. I can see why Malfurion puts his trust in you.\n\nGo and eliminate the source of this magic.", objectives = "Kill Morphael.", progress = "Someone entangled us within a sinister spell.", completion = "In my dreams, I saw the satyr's leader. His face was familiar, though I could not see it clearly.\n\nI pray to Elune that it is not too late. I will go to Malfurion at once." }
WordHunterWoW_QuestEN[38148] = { title = "Return to the Grove", description = "Now that my clan is assembled, we shall return to the Grove of Cenarius.\n\nSpeak to Malfurion when you arrive. We will find out the cause of Cenarius' illness.", objectives = "Return to Malfurion Stormrage at the Grove of Cenarius in Val'sharah.", completion = "Wonderful. The Archdruids have already assembled." }
