WordHunterWoW_QuestEN[38267] = { title = "Friends Above", description = "Iskar disappeared and now the Shadow Council is at our throats. These can't be unrelated events. We need to go to the last place he was seen, the ruins of Kra'nak.\n\nI've asked a friend to set up a camp nearby. I say we head there to continue our search.", objectives = "Meet with Reshad at Atkar's Post.", completion = "Ah, <name>. You're just in time.\n\nAktar says the Shadow Council are teaching the Sethekk their vile ways. There are even a group of High Arakkoa that have joined the Shadow Council's banner!\n\nI wonder how does Iskar factor into this?" }
WordHunterWoW_QuestEN[38268] = { title = "Darkbane", description = "", objectives = "" }
WordHunterWoW_QuestEN[38269] = { title = "Friends Above", description = "Iskar disappeared and now the Shadow Council is at our throats. These can't be unrelated events. We need to go to the last place he was seen, the ruins of Kra'nak.\n\nI've asked a friend to set up a camp nearby. I say we head there to continue our search.", objectives = "Meet with Reshad at Atkar's Post.", completion = "Ah, <name>. You're just in time.\n\nAktar says the Shadow Council are teaching the Sethekk their vile ways. There are even a group of High Arakkoa that have joined the Shadow Council's banner!\n\nI wonder how does Iskar factor into this?" }
WordHunterWoW_QuestEN[38270] = { title = "Finding the Killer", description = "With this map, you have pinpointed the origin of the attacks. It is time to see who or what is behind the attacks, and if they are a possible ally.", objectives = "Locate the slayer of Bleeding Hollow near Zeth'Gol.\n\nProvided item:", completion = "You... remember me? I came through the portal with you. I was called... Ariok. Before I became this." }
WordHunterWoW_QuestEN[38271] = { title = "Following the Bloody Path", description = "The ones I kill... they speak of a cave. Sacred to the Bleeding Hollow. Kilrogg could be there - I am going.", objectives = "Follow Ariok to the cave.", completion = "Old earth... old blood. I smell Kilrogg. He has been here." }
WordHunterWoW_QuestEN[38272] = { title = "The Bleeding Hollow", description = "The cave pulls me. It keeps angry spirits near. Kilrogg has done magic here. You help me understand...", objectives = "Reach the bottom of the Bleeding Hollow.", completion = "You step on hallowed ground, invader. Here the chieftains of the Bleeding Hollow have performed rituals to see the future.\n\nYou should die but there is much at stake..." }
WordHunterWoW_QuestEN[38273] = { title = "Spirits of the Bleeding Hollow", description = "It is clear the cave is protected by powerful ghosts, ancestors of the Bleeding Hollow.\n\nWhatever is down there, it will be easier to deal with if many of the spirits were dealt with first.", objectives = "Slay 6 Enraged Blood Spirits." }
WordHunterWoW_QuestEN[38274] = { title = "The Eye of Kilrogg", description = "If you wish to know what Kilrogg and his new master intend, you will need his eye. After the ritual all chieftains place their eye under the protection of the ghosts of the Bleeding Hollow in the next chamber.\n\nGo and locate the Eye of Kilrogg in the vault. The other chieftains will not stand with us, and will fight you for it.\n\nThen place it on the ritual mark nearby to get your answers.", objectives = "Find the Eye of Kilrogg and perform the scrying ritual.", progress = "What have you learned?", completion = "Bah. Kilrogg not here. Only omens and warnings. That is your path <name>, mine is to destroy Kilrogg..." }
