WordHunterWoW_QuestEN[38284] = { title = "Seeds of Remedy", description = "Several of my fellow druids have been gravely wounded. Although my restorative abilities will keep them stabilized, there is still more we can do to aid them.\n\n<Aaelar produces a handful of glowing seeds from his pouch.>\n\nThese are efflorescent seeds imbued with the blessing of nature. If I had more of them, I could create a potion that would greatly aid in the recovery of the wounded.\n\nHarvest the efflorescent saplings that grow near the fountain of Delyra and I will prepare the potion.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 50 Seeds of Remedy." }
WordHunterWoW_QuestEN[38285] = { title = "Menacing Sprites", description = "The local sprites are running amok and causing all sorts of problems!\n\nVal'sharah is home to a variety of forest and pond sprites will take any opportunity to spread mischief and chaos. It seems as though an especially wicked group of sprites have descended upon Thas'talah in the wake of the harpy invasion.\n\nThey are attacking the local wildlife and bullying the nearby faerie dragons. If you aid the local woodland creatures by taking care of the sprite menace, you will have our thanks.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay 10 sprites in Thas'talah." }
WordHunterWoW_QuestEN[38286] = { title = "Eye of Azshara: Wrath of Azshara", description = "{name}, Warlord Parjesh ran into the magical vortex just ahead. He has returned to an island off the shore to the southeast where Queen Azshara is staging more of her forces.\n\nThe queen is beyond angry because we opposed her. Even now, she is summoning up a monstrosity known as her Wrath to exact revenge for our defiance and drown the Broken Isles.\n\nYou must defeat the Wrath of Azshara before the queen lets it loose to destroy us all!", objectives = "Enter the Eye of Azshara, then defeat Warlord Parjesh and the Wrath of Azshara. The Eye of Azshara is a dungeon so be certain to gather some friends to undertake this perilous journey.", completion = "<The Tidestone of Golganneth stands whole and unprotected.>" }
