WordHunterWoW_QuestEN[38299] = { title = "Critters of Draenor", description = "I love collecting pets, and I've picked up a few unusual pets here in Draenor.  What would you say to a battle?  If you can defeat my humble team, I think we'll both learn a few new tricks.", objectives = "Defeat Erris the Collector in a pet battle.", progress = "Are we going to battle or what?", completion = "Not bad.  Not bad at all.  Stop by the next time I'm in the neighborhood, and I might have some new pets to check out." }
WordHunterWoW_QuestEN[38300] = { title = "Critters of Draenor", description = "I love collecting pets, and I've picked up a few unusual pets here in Draenor.  What would you say to a battle?  If you can defeat my humble team, I think we'll both learn a few new tricks.", objectives = "Defeat Kura Thunderhoof in a pet battle.", progress = "Are we going to battle or what?", completion = "Not bad.  Not bad at all.  Stop by the next time I'm in the neighborhood, and I might have some new pets to check out." }
WordHunterWoW_QuestEN[38304] = { title = "Val'sharah", description = "[PH] Go through the portal in Dalaran and meet Malfurion Stormrage in Val'Sharah.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Malfurion Stormrage at Lor'lathil in Val'Sharah.[PH] Go through the portal in Dalaran and meet Malfurion Stormrage in Val'Sharah.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38305] = { title = "Cenarius, Keeper of the Grove", description = "Greetings, hero.\n\nWelcome to Val'sharah. It has been an age since I have set foot in these precious woods. Too long...\n\nOur work here is simple. We must call upon my mentor, Cenarius, and learn where he safeguards the Tears of Elune. With them, you will be one step closer to sealing Sargeras' Tomb and thwarting the Legion.\n\nYou have many treacherous tasks in front of you. Consider your visit here a brief respite.\n\nCome, this will not take long.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Malfurion Stormrage at Lorlathil in Val'Sharah." }
WordHunterWoW_QuestEN[38306] = { title = "Mystery Notebook", description = "This book has seen better days. Not much can be made out between the waterlogging and the apparent animal bites, but a few poor attempts at poetry center around the \"radiant glow\" of the Undercity and someone named Estelle Gendry.", objectives = "Return the notebook to Estelle Gendry in the Undercity.", completion = "<Estelle pages through the damaged tome and sighs wistfully.>\n\nOh dear, another paramour dead! Draenor has a terrible habit of eating my lovers alive." }
WordHunterWoW_QuestEN[38307] = { title = "The Warchief Beckons", description = "Greetings, {name}. I am here on behalf of Lady Sylvanas Windrunner. I should hope you recognize the name.\n\n<Nathanos thrusts a sealed envelope into your hand.>\n\nRead it and follow me.\n\nYou can read, can't you?", objectives = "Read the Royal Summons and follow Nathanos Blightcaller through the portal to Durotar.", progress = "If only she weren't so specific about bringing you to her unharmed...", completion = "Satisfied?" }
WordHunterWoW_QuestEN[38308] = { title = "Eyes in the Overlook", description = "Alliance personnel from the Skyfire were spotted parachuting into Blackbeak Overlook.\n\nI was unable to confirm numbers or positions during my flyover, but I did see parachutes tangled in treetops and a LOT of ravenbears on the ground.\n\nIf anyone is up there, they must be laying low and keeping an eye on us.\n\nI have posted a rider at the top of the overlook to keep watch while I press forward into Stormheim.\n\n- Liza Cullen, Dread-Rider - 1st Wing", objectives = "Recover the SI:7 Intel from Spymaster Knockwhistle in Blackbeak Overlook." }
WordHunterWoW_QuestEN[38309] = { title = "Content Perk: The Light Reveals", description = "", objectives = "" }
WordHunterWoW_QuestEN[38310] = { title = "Content Perk: Righteous Strength", description = "", objectives = "" }
WordHunterWoW_QuestEN[38311] = { title = "Content Perk: Call of the Highlord", description = "", objectives = "" }
WordHunterWoW_QuestEN[38312] = { title = "A Grapple a Day", description = "So these trials are what will get us the Aegis, and the next one is on the top of that mountain? That may prove problematic.\n\nThe only way I see up the mountain is through that vrykul city, and the gates are shut tight. We should be able to grapple over, though. If you don't have a launcher, I managed to wrangle a spare from one of these vrykul.\n\nI'll scout ahead and see if I can find a good spot to get in.", objectives = "Pick up a Stormforged Grapple Launcher and meet Lorna Crowley outside the wall of Hrydshal.", completion = "That looks like it'll do the job nicely. \n\nLet's get in there before we're spotted." }
WordHunterWoW_QuestEN[38314] = { title = "Vignette: Hidden Demon", description = "", objectives = "" }
WordHunterWoW_QuestEN[38315] = { title = "DEPRECATED", description = "You know what would boost morale around here?\n\nBass. Beats. Music!\n\nEveryone loves a party! You go out and get me some hardware, and I'll make a system that will shatter Draenor itself.", objectives = "Collect a Bass Blaster, Laz-tron Disc Reader, Phonic Amplifier, S.P.R.K. Capacitor, and a Cord of Ancient Wood." }
WordHunterWoW_QuestEN[38316] = { title = "Azsuna - Treasure 014 - Fel Collector", description = "", objectives = "" }
WordHunterWoW_QuestEN[38317] = { title = "Masters of Disguise", description = "<You scan over Knockwhistle's report.>\n\n\"My chute caught a piece of shrapnel. Made a rough landing in a ravenbear nest. Luckily, a bunch of eggs broke my fall.\n\nLost sight of Illandris and Shwayder. Both are masters of disguise, and I am confident they can remain undetected.\n\nWill continue to monitor the enemy's activity. Just need to clean all the yolk off my cloaking device. Hope the mother's not around...", objectives = "Slay Spymaster Illandris and Spymaster Shwayder.", progress = "We cannot speak freely - the Alliance have eyes and ears in the hills.", completion = "Finally, I can get back to the action!" }
WordHunterWoW_QuestEN[38318] = { title = "No Wings Required", description = "Now that you've got the launcher, we should be able to infiltrate the city. It looks like there's a good spot to grapple onto on the wall just past us. There's a vantage point on top of this ridge.\n\nOnce we're in, I'll try to slip past the guards and get a look at the mountain path. I'd appreciate if you could make some distractions for me. If all goes well, I'll meet up with you in the upper city.\n\nGood luck!", objectives = "Go to the top of the ridge and use the Stormforged Grapple Launcher to launch over the wall at Hrydshal.", completion = "You should've seen the look on those vrykuls' faces when you came sailing over their wall! \n\nI could see that launcher coming in handy in a lot of places. You'd best hold on to it." }
WordHunterWoW_QuestEN[38320] = { title = "Treasure: The Blade of Kra'nak", description = "", objectives = "" }
WordHunterWoW_QuestEN[38321] = { title = "Blackbeak Overlook", description = "", objectives = "" }
WordHunterWoW_QuestEN[38322] = { title = "Return to the Grove", description = "Now that my grove is safe, I can turn my attention to the threat you speak of.\n\nTo hear of Cenarius' plight is disturbing indeed. Tell Malfurion that I shall meet him at the Grove.", objectives = "Return to Malfurion Stormrage at the Grove of Cenarius in Val'sharah.", completion = "Wonderful. The Archdruids have already assembled." }
WordHunterWoW_QuestEN[38323] = { title = "Return to the Grove", description = "Forgive me, {race}. Archdruid Moonclaw's fall is a terrible blow...\n\nMalfurion must be informed of what has transpired here. Inform him of Thaon's fate and of the return of Xavius.\n\nMake haste, friend. I fear this may be the greatest threat Val'sharah has ever faced.", objectives = "Return to Malfurion Stormrage at the Grove of Cenarius in Val'sharah.", completion = "Thaon will be dearly missed. We may not have always seen eye to eye, but he was a great druid and a true protector of the vale.\n\nXavius will pay for his death..." }
WordHunterWoW_QuestEN[38324] = { title = "Accessories of the Cursed", description = "Wait! Before ye go rushin' off, we might want to be gettin more than just seaweed. \n\nYe see, these vrykul also be carrying bones with them - worn all over like jewelry. If ye can get yer hands on some of the bones they got lyin around, it'll add to the disguise.\n\nSo what ye waitin for?", objectives = "Collect 8 Cursed Bones in Helheim.", progress = "Make sure ye've got enough bones before we move on.", completion = "Ah yes, these will do. \n\nNow lets see what we can make to fool old Guarm, eh?" }
WordHunterWoW_QuestEN[38331] = { title = "Havi's Test", description = "I could sense your power the moment you arrived in this land. You carry great purpose and a heavy task.\n\nKnow that the Aegis of Agrammar rests in the high halls of the All-Father. Only if you prove your valor, can you claim it against your foe.\n\nMany trials must you face for this, but first I must know your strength. My stew is incomplete, and my old bones couldn't carry the ingredients up the hill. \n\nYou look like you have a good arm. Will you help an old man finish his stew?", objectives = "Toss ingredients from the Basket of Root Vegetables, Barrel of Crabs, and Hearty Vrykul Grains into Havi's Stewpot.", progress = "Smells good, doesn't it?", completion = "Hah, you throw like a shieldmaiden!\n\nWhat? That's a good thing! \n\nTry the stew, young champion, and savor the taste of a task well done." }
WordHunterWoW_QuestEN[38332] = { title = "The Ranger Lord", description = "Good to see you survived the wreck. Nathanos made it as well, though his face is now even uglier than before.\n\nHe took a group of rangers north to look for Sylvanas - nobody has seen her since the battle.\n\nHe asked me to send you his way if you ever woke up.", objectives = "Report to Nathanos Blightcaller.", completion = "<Nathanos narrows his eyes at the wreckage of Sylvanas' ship.>\n\nShe's out there... she has to be." }
WordHunterWoW_QuestEN[38333] = { title = "Vignette: Drake Wrestler", description = "", objectives = "" }
WordHunterWoW_QuestEN[38334] = { title = "Treasure: Jewel of Hellfire", description = "", objectives = "" }
WordHunterWoW_QuestEN[38337] = { title = "Built to Scale", description = "The vrykul around here seem to use scales from these drakes to fashion their armor. \n\nIf you were able to gather enough material from the local drakes, you may be able to make something useful out of it.", objectives = "Collect Storm Drake Scales from the Stormwing drakes in Hrydhsal.", progress = "Oh, what do you have there?", completion = "Good thinking gathering up these scales. \n\nIt should be simple enough to make a solid piece of armor from them." }
WordHunterWoW_QuestEN[38339] = { title = "A Little Kelp From My Foes", description = "I'm not sure what yer doin' here, but ye have my thanks. If ye want to get any further, though, ye'll need to get past that foul dog, Guarm.\n\nI've tried meself a few times, and I think I have a plan. If we can get some of the seaweed these kvaldir wear, we might be able to trick the mutt. Guarm's mean, ye see, but not too smart.\n\nWhat do ye say? Think ye can take on a few kvaldir?", objectives = "Collect 20 pieces of seaweed from Kvaldir Mistcallers and Soulflayers in Helheim.", progress = "Do ye have enough for a proper disguise?", completion = "Wait... ye killed how many kvaldir? Yer braver than I thought, outsider!\n\nI'm sure Helya will see that neither ye nor I belong here once we get past that dog of hers." }
WordHunterWoW_QuestEN[38341] = { title = "Halting the Nightmare", description = "The corruption of the vale is the work of satyrs.\n\nThe new power they wield is unlike any I've seen... it is dark, seething and terrible.\n\nNefarious demon totems help spread their taint upon the land.\n\nThe Nghtmare totems must be destroyed if we are to hold back the tide of corruption.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Destroy 3 Nightmare Totems in the Moonclaw Vale." }
WordHunterWoW_QuestEN[38342] = { title = "Another Way", description = "Well, the bridge option is out. You still got that grapple launcher handy?\n\nIt looks like we can get across from the top of that tower over there. First thing's first, though, we'll need to deal with the big ugly sitting out front.\n\nYou take point.", objectives = "Defeat Gunnlaug Scaleheart in Hrydshal, then climb to the top of the tower.", progress = "Well, we made it this far...", completion = "Well, there's no stopping you, is there?" }
WordHunterWoW_QuestEN[38343] = { title = "Raze Hel", description = "", objectives = "" }
WordHunterWoW_QuestEN[38344] = { title = "Mystery Notebook", description = "This book has seen better days. Not much can be made out between the waterlogging and the apparent animal bites, but you can make out some sort of Ironforge-based drinking game scoring system involving a dwarf named Krom Stoutarm.", objectives = "Return the notebook to Krom Stoutarm in Ironforge.", completion = "Oh now, this brings back some memories. Y'didn't look at the scores did you?\n\nThis belonged to ol' Nolan, may he rest in peace. Not a very good explorer, but a helluva drinker." }
WordHunterWoW_QuestEN[38345] = { title = "Numismatics", description = "I hate to be too cynical, but I don't think we're gonna find Nolan in one piece. Or in a lot of pieces.\n\nNolan was a nut for finding rare coins. He's been from one end of the world to the other finding them, and now he's gone and gotten himself killed looking for more mint condition Draenei coins. Tell you what - let me show you what these coins look like, you bring me a few more of them and I'll set up an exhibit in his honor.", objectives = "Bring Misprinted Draenic Coins to Krom Stoutarm in Ironforge. Misprinted Draenic Coins can be found when completing your first Random Heroic Draenor dungeon each day.", progress = "How's the coin hunt going?", completion = "These are in great condition. Nolan would be green with envy." }
WordHunterWoW_QuestEN[38346] = { title = "Numismatics", description = "I told him this was a fool's errand. Of course he would get himself killed over a handful of coins! Oh well, there are always new lovers to find.\n\nYou'll have to do in the mean time. And you are quite easy on the eyes, aren't you? Be a dear and find me more coins that look like this one? I need them for... research.", objectives = "Bring Misprinted Draenic Coins to Estelle Gendry in Undercity. Misprinted Draenic Coins can be found when completing your first Random Heroic Draenor dungeon each day.", progress = "Well? Do you have the coins I asked you to find?", completion = "Excellent work. I knew you'd be useful, sugarplum.\n\nThere's something very unusual about these coins..." }
WordHunterWoW_QuestEN[38347] = { title = "Stealth by Seaweed", description = "There! The disguise be complete!\n\nDon't mind the smell, there. It's probably better that we smell like the kvaldir, as well. Though I have a feeling I'll be needin a priest to get this stench out once we're gone.", objectives = "Use the Kvaldir Disguise to sneak by Guarm.", progress = "Gods, what is that stench?! \n\nThis disguise had better work!", completion = "That was a truly revolting, outsider. Even in death I've never witnessed such a disgusting smell." }
WordHunterWoW_QuestEN[38348] = { title = "Unlock \"Silvermoon\"", description = "", objectives = "" }
WordHunterWoW_QuestEN[38351] = { title = "Portable Portals", description = "My assistants have figured out how to convert ogre waystones into useful items for our garrison. Speak with Varsha outside to start your first work order.", objectives = "Speak with Varsha outside the Spirit Lodge.", progress = "Did you find Varsha?", completion = "I see you found Varsha.  Now, keep him supplied with waystones and we will be well on our way to defeating the iron horde." }
WordHunterWoW_QuestEN[38352] = { title = "Kazrok", description = "", objectives = "" }
WordHunterWoW_QuestEN[38353] = { title = "Rescued From Darkness", description = "Midnight Vale is home to a unique breed of Nightsaber known as the Vale Prowler. For centuries, our clan has lived in harmony with these great feline hunters.\n\nHowever, even as we speak satyrs are twisting and corrupting the vale into a place of death and nightmare. Even the forest itself lashes out in torment against the living, causing many of the forest creatures to flee the vale.\n\nI fear for the safety of the youngest nightsabers, who may yet be caught in the twisting chaos, unable to escape.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Save 7 Prowler Cubs in The Midnight Vale." }
WordHunterWoW_QuestEN[38354] = { title = "Portable Portals", description = "My assistants have figured out how to convert ogre waystones into useful items for our garrison.  Speak with Apprentice Var'nath outside to start your first work order.", objectives = "Speak with Apprentice Var'nath outside the Mage Tower.", completion = "I see you found Apprentice Var'nath.  Now, keep him supplied with waystones and we will be well on our way to defeating the iron horde." }
WordHunterWoW_QuestEN[38355] = { title = "7.0 Val'sharah - Treasure 002 - Moonrest Shore - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[38356] = { title = "Bringing the Bass", description = "It's a bit quiet around here, in between the invasions and all.\n\nYou're in luck though, Commander! I can fix that, and boost morale among your troops all at the same time.\n\nAll you need to do is bring me a few items from around Draenor, and I'll fill your garrison with music. I'll even throw in a few music rolls from my own collection to get you started!\n\nWhat do you say?", objectives = "Collect a Bass Blaster, Laz-Tron Disc Reader, Phonic Amplifier, S.P.R.K. Capacitor, and a Cord of Ancient Wood.", progress = "Collect a Bass Blaster, Laz-Tron Disc Reader, Phonic Amplifier, S.P.R.K. Capacitor, and a Cord of Ancient Wood.", completion = "This is the best Draenor has to offer? Lucky for you I went to engineering school. One Tune-O-Tron 5000 coming up!" }
WordHunterWoW_QuestEN[38357] = { title = "Side Effects May Include Mild Undeath", description = "Exposure to this particular \"byproduct\" is quite nasty.\n\nRapid cell degeneration quickly reduces the subject to a shambling husk incapable of any reason or thought beyond a violent, throbbing hatred for the warmth of life.\n\nAs you might imagine, the local fauna have been affected by the spill. Oh, and most of the crew as well...\n\nAnyway, good luck!", objectives = "Slay 10 Volatile Bears or Volatile Sailors.", progress = "Come now, surely you don't intend to leave them in this state? Have you no compassion?\n\nHow about money - you like money, don't you?", completion = "The R.A.S. is nothing if not humane." }
WordHunterWoW_QuestEN[38358] = { title = "Pump it Up", description = "The Black Rose was a seafaring laboratory for the Royal Apothecary Society. Naturally, we had some volatile... \"byproducts\" onboard.\n\nRegrettably, one such substance was released during our skirmish with the Alliance gunship. As you can see, it is taking quite a toll on the coast.\n\nThe R.A.S. must remedy this situation before we press further inland.\n\nPlease take a containment unit and fill it with waste - for us to dispose of properly at a later time, of course.", objectives = "Fill the Containment Unit with Volatile Waste.", progress = "There's still room in that containment unit.", completion = "Wonderful, just put that down anywhere. Careful not to spill it!\n\n<The apothecary snickers.>" }
WordHunterWoW_QuestEN[38359] = { title = "7.0 Val'sharah - Treasure 003 - Lorlathil - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[38360] = { title = "The Windrunner's Fate", description = "Finding Sylvanas is our only priority!\n\nWe will cover more ground if we split up. I will lead a team into the hills above the enemy's camp while you search the wreckage itself for any signs of the crew.\n\nOnce we've cleared the high ground, I will meet you at the far end of the beach.", objectives = "Search the wreckage of the Windrunner and the nearby coastline for signs of Sylvanas.", completion = "So, she escaped after all..." }
WordHunterWoW_QuestEN[38361] = { title = "Wrath of the Blightcaller", description = "The Alliance dogs have bitten off more than they can chew. They have attacked the Banshee Queen, and invoked the wrath of her champion!\n\nLike my bow, my axes, and my hounds, you will be an agent of vengeance. Pile the bodies high, {class}, and know that I am doing the same. When next we meet, I expect to see blood upon your hands.", objectives = "Slay 15 7th Legion Paratroopers or Skyfire Gryphon-Riders.", progress = "I have no use for soft buffoons! Begone if you haven't the stomach for vengeance!", completion = "They have only begun to pay for their insolence." }
WordHunterWoW_QuestEN[38362] = { title = "A Grim Trophy", description = "It would seem Sylvanas does not wish to be followed - by us or anyone else.\n\nHer will is her own, it is not my place to question. Only to obey.\n\nIn the hills nearby, a gryphon master is preparing to take flight, no doubt to pursue our queen from the sky. My rangers are lying in wait - we need only to close our jaws around him.\n\nI will have his head when this is over.", objectives = "Take the Head of Thane Wildsky.", progress = "Do you have his head?", completion = "Look carefully at this head, <name>. This is what comes to those who stand against the Forsaken.\n\nFor now, we should begin our search for the Aegis of Agrammar. I will send some scouts out to discern its location. You should start your search as well. \n\nWhat are you waiting for?" }
WordHunterWoW_QuestEN[38363] = { title = "7.0 Val'sharah - Treasure 004 - Thas'talah Basin - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[38365] = { title = "Azsuna - Treasure 015 - Giblin Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[38366] = { title = "7.0 Val'sharah - Treasure 005 - Thas'talah - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[38367] = { title = "Azsuna - Treasure 016 - Cask of Special Reserve", description = "", objectives = "" }
WordHunterWoW_QuestEN[38368] = { title = "Vignette: Hidden Demon", description = "", objectives = "" }
WordHunterWoW_QuestEN[38369] = { title = "7.0 Val'sharah - Treasure 006 - Ravencourt - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[38370] = { title = "Azsuna - Treasure 017 - Wedding Tablet", description = "", objectives = "" }
WordHunterWoW_QuestEN[38371] = { title = "7.0 Val'sharah - Treasure 007 - Sylvan Lake - ZtO", description = "", objectives = "" }
WordHunterWoW_QuestEN[38372] = { title = "Wretched Sisters", description = "", objectives = "" }
WordHunterWoW_QuestEN[38374] = { title = "Assault the Drekirjar", description = "", objectives = "" }
WordHunterWoW_QuestEN[38376] = { title = "The Search for the Highlord", description = "Tirion is fading away on that infernal shore... and the Ashbringer with him! We must not waste another moment.\n\nGive the word and we'll set off. We're ready when you are.", objectives = "Recover Tirion Fordring and the Ashbringer from the Broken Shore.", progress = "<Maxwell's eyes seem to struggle to meet your own.>", completion = "I owe you my life, <name>. We all do." }
WordHunterWoW_QuestEN[38377] = { title = "The Emerald Queen", description = "{name}, you have returned. Good.\n\nI have counseled with the other archdruids and concluded that Cenarius' condition is merely a symptom of a much greater problem. Your experiences in Moonclaw Vale make that clear.\n\nWe need help.\n\nThere is one who can bring understanding to these events. With Thaon gone, we must ask that you aid us in reaching out to the Lady of Dreams.", objectives = "Speak to Malfurion when ready.", completion = "Behold, Ysera, the Emerald Queen." }
WordHunterWoW_QuestEN[38380] = { title = "Vignette: Hivequeen Zsala", description = "", objectives = "" }
WordHunterWoW_QuestEN[38381] = { title = "Archdruid of Lore", description = "Elothir resides in the ancient grove Thas'talah, where he communes with nature and instructs his acolytes in the ways of healing and the preservation of lore.\n\nSeek him out and tell him that he is desperately needed here.", objectives = "Seek out Elothir in Thas'talah.", completion = "Welcome, traveler." }
WordHunterWoW_QuestEN[38382] = { title = "Archdruid of the Vale", description = "Deep within our forest lies Moonclaw Vale.\n\nThere you will find a reclusive group of feral druids charged with the protection of Val'sharah from any that would seek to disrupt the balance of nature.\n\nThese druids are led by Thaon Moonclaw, the most fierce of the Archdruids.\n\nSeek him out. Let him know that Cenarius is in need of his aid.", objectives = "Speak with Thaon Moonclaw.", completion = "Cenarius will have my aid once my grove has been made safe." }
WordHunterWoW_QuestEN[38383] = { title = "7.0 Stormheim - Treasure 019 - Helheim - ZTO", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38384] = { title = "Nature's Call", description = "What vile power is this?!\n\nA curse with the strength to paralyze a demigod? Unimaginable!\n\nQuickly, {name}, you must gather the archdruids of the forest. With their help, we can summon Ysera. She will surely know what horror has overtaken my mentor.\n\nI will remain here and lend Cenarius what aid I can.\n\nReturn to Lorlathil and speak with Aranelle. She will know the archdruids' whereabouts.\n\nAnd please, friend, make haste...", objectives = "Speak to Aranelle in Lorlathil.", completion = "Cenarius is in need? Lord of the Forest, we shall not fail you..." }
WordHunterWoW_QuestEN[38386] = { title = "7.0 Val'sharah - Treasure 008 - Shadowfen - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[38387] = { title = "7.0 Val'sharah - Treasure 009 - Val'sharah - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[38388] = { title = "7.0 Val'sharah - Treasure 010 - Val'sharah - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[38389] = { title = "7.0 Val'sharah - Treasure 011 - Val'sharah - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[38390] = { title = "7.0 Val'sharah - Treasure 012 - Grove of Cenarius - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[38391] = { title = "7.0 Val'sharah - Treasure 013 - Val'sharah - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[38392] = { title = "7.0 Val'sharah - Treasure 014 - Malorne's Refuge - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[38393] = { title = "7.0 Val'sharah - Treasure 015 - Malorne's Refuge - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[38394] = { title = "Completionism", description = "Interesting - the coins you've brought back from your Garrison are slightly different than the ones Nolan collected in Outland. Y'see here, the markings along the edge? Very interesting stuff! This requires some more study an' that means more coins! Bring them to me and I'll see if I can scrounge up something for your trouble.", objectives = "Bring Misprinted Draenic Coins to Krom Stoutarm in Ironforge. Misprinted Draenic Coins can be found when completing your first Random Heroic Draenor dungeon each day.", progress = "Aye? Y'got them coins yet?", completion = "Y'know, I think we might be on to somethin' big here." }
WordHunterWoW_QuestEN[38395] = { title = "Completionism", description = "This is intolerable! The coins you brought me do not match the rest of the coins I already have! You aren't counterfeiting these are you? No? Hrumph. In that case I'm sorry we fought, dearie.\n\nThere's only one thing to do, buttercup: we need to complete the new set you've discovered. Bring me more misprinted coins!", objectives = "Bring Misprinted Draenic Coins to Estelle Gendry in Undercity. Misprinted Draenic Coins can be found when completing your first Random Heroic Draenor dungeon each day.", progress = "I certainly hope these coins can complete this set so I can se-- er, so I can treasure them forever.", completion = "That wasn't so hard now was it, peaches?\n\n<Estelle holds the coins you brought up the the light and practically purrs.>\n\nYes yes, these are so very strange..." }
WordHunterWoW_QuestEN[38396] = { title = "A Curious Oddity", description = "I've been looking at some of the other coins in circulation plus the ones you've brought back. Some o' these are misprints... others are just plain wrong. Look 'ere. This one's got two heads. And the second one is smiling at me, where it wasn't before.\n\nThere's a bigger mystery in play here and these misprints are the key to figuring it out. I'm gonna need even more.", objectives = "Bring Misprinted Draenic Coins to Krom Stoutarm in Ironforge. Misprinted Draenic Coins can be found when completing your first Random Heroic Draenor dungeon each day.", progress = "We're on the verge of a breakthrough here.", completion = "Good, good! I've got some awful suspicious suspicions about these here suspicious coins." }
WordHunterWoW_QuestEN[38397] = { title = "A Curious Oddity", description = "Well sweet pea, I have good news and bad news for you. The good news is that you brought me enough coins to complete this new misprint set! The bad news is that not a single one of them has matched the original partial set.\n\nSee here - this coin has two heads. And the face on the reverse is grinning at me, where he was looking so dour only an hour ago. This one squints when I shine a light on it. Such a mystery! I must have more!", objectives = "Bring Misprinted Draenic Coins to Estelle Gendry in Undercity. Misprinted Draenic Coins can be found when completing your first Random Heroic Draenor dungeon each day.", progress = "Has anyone told you today that you're beautiful? You are.", completion = "Honeybiscuit, when this is all over, you and I may be remembered as stumbling on a great paranormal discovery. Or I will at least." }
WordHunterWoW_QuestEN[38398] = { title = "Vignette: Helyra's Kraken", description = "", objectives = "" }
WordHunterWoW_QuestEN[38399] = { title = "Fencing the Rose", description = "Looking to sell something?", objectives = "Looking to sell something?", progress = "Looking to sell something?", completion = "Ah yes, an eternium rose.  I heard vendors suddenly stopped buying them... something about the resell value being too low.\n\nYou're in luck though, because I know a collector who still wants them.  In fact, I can take this one off your hands, but you'll have to come back tomorrow if you have another one to sell." }
WordHunterWoW_QuestEN[38400] = { title = "Vignette: Grand Warlock Nethekurse", description = "", objectives = "" }
WordHunterWoW_QuestEN[38401] = { title = "DEPRECATED", description = "You know what would boost morale around here?\n\nBass. Beats. Music!\n\nEveryone loves a party! You go out and get me some hardware, and I'll make a system that will shatter Draenor itself.You will learn:", objectives = "Collect a Bass Blaster, Laz-tron Disc Reader, Phonic Amplifier, S.P.R.K. Capacitor, and a Cord of Ancient Wood." }
WordHunterWoW_QuestEN[38402] = { title = "The Same, But Different", description = "I'm beginning to suspect these here coins are demonic. See? This one's got three eyes! This one always comes up tails. And over here - the ones you brought me earlier? They dissolved in holy water.\n\nI need to make absolutely sure this isn't a fluke - bring me a huge pile of coins to sort through so nobody can refute m'theory.", objectives = "Bring Misprinted Draenic Coins to Krom Stoutarm in Ironforge. Misprinted Draenic Coins can be found when completing your first Random Heroic Draenor dungeon each day.", progress = "Incredible work. Yer gonna be a hero in the Explorer's League for sure.", completion = "Aye, I've been talkin' to the priests in the Mystic Ward and they confirmed my sucpicions. These 'misprinted' coins are all demonic in origin.\n\nYeh done a good deed takin' these out of circulation. Well done, <name>!" }
WordHunterWoW_QuestEN[38404] = { title = "The Same, But Different", description = "A most intriguing theory has been put forth by an associate of mine that may explain what's wrong with these coins. We believe they might be demonic in origin. See? This one's got three eyes. And this one always comes up tails. And THIS one whispers to me at night - on now, don't be jealous sweetheart. You're still my favorite.\n\n...Provided you bring me more coins so I can confirm our theory. Run along!", objectives = "Bring Misprinted Draenic Coins to Estelle Gendry in Undercity. Misprinted Draenic Coins can be found when completing your first Random Heroic Draenor dungeon each day.", progress = "You've done a most wonderful service for me. I won't forget you, sweetheart. At least not this week.", completion = "I am most gracious for your services. So many coins! Such a foul energy within them - do you feel it? Somebody was trying to corrupt the draenei from within.\n\nWell, don't you worry your pretty head any. My colleagues and I will take VERY good care of these. Thank you, lovely!" }
WordHunterWoW_QuestEN[38405] = { title = "To Weather the Storm", description = "I've been doing some nosing around, and it looks like these vrykul are making regular trips up the mountain themselves. They've got some specialized gear for it, so while we're here we should take some.\n\nI'd recommend finding some climbing treads to keep your grip on the slopes, as well as an oiled cloak to keep the rain out. Also, it looks like they carry enchanted lodestones, which seem to keep the lightning at bay. You should probably grab one of those, too.", objectives = "Collect Climbing Treads, an Oiled Cloak, and an Enchanted Lodestone from Hrydshal.", progress = "Did you find everything?", completion = "Excellent. These should do well to protect you from the storm." }
WordHunterWoW_QuestEN[38406] = { title = "Sea Scorpion Lunker", description = "", objectives = "A monstrous sea scorpion?", progress = "A monstrous sea scorpion?", completion = "This big fella must have been growing for years.  To be honest, it's so cute I'll probably just let it go.  Maybe you can catch it again one day!" }
WordHunterWoW_QuestEN[38407] = { title = "Bottled Up", description = "<You've found a message in a bottle on the corpse. It's a request for aid from someone named Okuna Longtusk. Okuna claims that he and his fellow shipmates are being held prisoner by sea giants.\n\nMaybe if you show the note to the ghost of Lady Irisse at the Crumbled Palace, she can point you in the right direction?>", objectives = "Take Okuna's Message to Lady Irisse.\n\nProvided item:", completion = "You say you found this message in a bottle? How quaint.\n\nYes, I can point you in the right direction, but are you sure you want to take on the sea giant prince and his skrogs? Just to free a bunch of unwashed sailors?" }
WordHunterWoW_QuestEN[38408] = { title = "New Goods", description = "New items are available from Sergeant Crowler.  I suggest you stop by and take a look at his new goods as soon as you can!", objectives = "Talk with Sergeant Crowler." }
WordHunterWoW_QuestEN[38410] = { title = "Impalement Insurance", description = "I've got bad news. Those harpoon launchers up on the walls might cause us some problems. \n\nThey can't get at us down here, but once you start climbing that path, they're likely going to try to skewer you.\n\nIf you use that grapple launcher, you should be able to get on top of the walls and dismantle them. Watch out for the drakes, though!", objectives = "Grapple on top of the walls in Hrydshal and dismantle 7 Tideskorn Harpoon Launchers.", completion = "Hah! I bet they never saw that coming!\n\nSeems like we've got no shortage of obstacles left, though." }
WordHunterWoW_QuestEN[38411] = { title = "Vignette: Executor Riloth", description = "", objectives = "" }
WordHunterWoW_QuestEN[38412] = { title = "Above the Winter Moonlight", description = "You should have a good vantage from this tower to grapple over to the mountain path. I can't help you once you're across, but you should be able to take it all the way up to the top. \n\nI hope you're able to find what you need from the dragons up there. Who knows what the God-King has done to them.", objectives = "Grapple across from the tower and climb to the top of the mountain path.", completion = "You are here for the trial? I'm afraid you might be too late.\n\nThis battle with these Felskorn has taken its toll. I am too weak to grant you the power you seek...\n\nBut perhaps you may be able to help..." }
WordHunterWoW_QuestEN[38413] = { title = "Wings of Liberty", description = "When the Felskorn assaulted the nest, the Thorignir fought bravely to save our brood. But their demonic allies proved too much, and many of us were captured.\n\nEven now they work to corrupt my brothers and sisters to turn them to their side. \n\nPlease, outsider, free them from this fate!", objectives = "Free Aleifir, Hrafsir, Erilar and Hridmogir in Thorim's Peak.", progress = "What news do you bring of my brothers and sisters?", completion = "I am truly indebted to you for this act. My siblings were not able to defend themselves against the Felskorn, and would have ended up their slaves. \n\nYou are a true friend of the Thorignir." }
WordHunterWoW_QuestEN[38414] = { title = "Heart of a Dragon", description = "Through brute force and corruption, the God-King has taken the power you seek, but there may be hope for you and the Thorignir, {class}.\n\nWith the aid of fel powers such as I've never seen, the Felskorn are corrupting our young and seeking to enslave the Thorignir. Their leader, a demon of great power, has captured our mother and seeks to bend her to the God-King's will.\n\nFind her and free her from the demon's grasp - only then might the Thorignir regain our power and grant you aid.", objectives = "Find and rescue the mother of the Thorignir brood.", progress = "Have you found our brood-mother?", completion = "I am relieved to hear that our mother is safe. \n\nI am sure she will wish to thank you herself." }
WordHunterWoW_QuestEN[38415] = { title = "Garrison Campaign: Onslaught at Auchindoun", description = "Your ally, Liadrin, has sent a missive requesting aid near Auchindoun. The Sargerei have made a new assault there and breached something important. It is no coincidence this happened after Gul'dan's ascendancy. We will watch the front here, commander.", objectives = "Meet Liadrin at Auchindoun in Talador.", completion = "I know the battle for Tanaan presses sorely on your forces commander. I am glad you came. The Sargerei and Gul'dan have the same masters, so this new attack likely affects you as well." }
WordHunterWoW_QuestEN[38416] = { title = "Secrets of the Sargerei", description = "The Auchenai have been reporting for some time that something was... wrong... with Auchindoun. They were never able to find a reason. Suddenly the Sargerei attacked and blew open a hole into a subchamber.\n\nCorruption leaks from that hole, we need to stop it.", objectives = "Locate and stop the source of corruption underneath Auchindoun.", completion = "This is unfortunate. We cannot allow Gorefiend to aid Gul'dan's machinations. He must be slain once and for all." }
WordHunterWoW_QuestEN[38417] = { title = "The Sargerei Menace", description = "An attack such as this was unexpected. They have deployed heavily and it will take me some time to marshal enough forces to root them out.\n\nAny Sargerei you can slay will make retaking this area much easier commander.", objectives = "Slay 12 Sargerei." }
WordHunterWoW_QuestEN[38419] = { title = "Azsuna - Treasure 018 - [The Greenway]", description = "", objectives = "" }
WordHunterWoW_QuestEN[38421] = { title = "Garrison Campaign: Onslaught at Auchindoun", description = "The Auchenai have sent me an urgent missive - Auchindoun is in jeopardy again! The Sargerei have renewed their assault  and breached the underhalls. I sense the hand of Gul'dan is behind this.\n\nGather your things and meet me in the Court of Souls West of Auchindoun at once!", objectives = "Meet Yrel at Auchindoun in Talador.", completion = "I am glad you came at once. Something terrible is brewing beneath this holy place." }
WordHunterWoW_QuestEN[38422] = { title = "Makrura Wave Event", description = "", objectives = "" }
WordHunterWoW_QuestEN[38423] = { title = "Vignette: Stormdrake Matriarch", description = "", objectives = "" }
WordHunterWoW_QuestEN[38424] = { title = "Thane's Mead Hall", description = "", objectives = "" }
WordHunterWoW_QuestEN[38425] = { title = "Vignette: Fel Thorignir", description = "", objectives = "" }
WordHunterWoW_QuestEN[38426] = { title = "Treasure: Tome of Secrets", description = "", objectives = "" }
WordHunterWoW_QuestEN[38427] = { title = "New Goods", description = "New items are available from Sergeant Grimjaw.  I suggest you stop by and take a look at his new goods as soon as you can!", objectives = "Talk with Sergeant Grimjaw." }
WordHunterWoW_QuestEN[38428] = { title = "A Fel Puppy Of My Own", description = "", objectives = "<Tentatively, the pup licks your hand. After receiving a good scratch behind the ears, the pup barks and wags its tail.>" }
WordHunterWoW_QuestEN[38430] = { title = "Vignette: Argosh the Destroyer", description = "", objectives = "" }
WordHunterWoW_QuestEN[38431] = { title = "Vignette: Bladesquall", description = "", objectives = "" }
WordHunterWoW_QuestEN[38433] = { title = "Tanaan Jungle - Tracking Quest - Lion's Watch Built - JMC", description = "", objectives = "" }
WordHunterWoW_QuestEN[38434] = { title = "The Ashbringer", description = "The blade fell... during the battle... Broken Shore...\n\n<Tirion coughs up blood.>\n\nMy time... is short. You must go ahead... into the temple ruins...\n\nYou must... retrieve...\n\n...the Ashbringer.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Retrieve the Ashbringer from the Lost Temple at the Broken Shore." }
WordHunterWoW_QuestEN[38435] = { title = "The Invasion of Tanaan", description = "It is done! By your command we have built our first ship and can run our naval operations from here.\n\nNow that we have our transport, we can let Yrel and Archmage Khadgar know that we are ready to kick off an invasion of Tanaan. Speak with them at the docks to embark.", objectives = "Meet with Khadgar at your shipyard and then speak to Yrel to begin the invasion.", completion = "The landing was easier than I expected but there is trouble ahead." }
WordHunterWoW_QuestEN[38436] = { title = "Obstacle Course", description = "Our landing was unopposed. Why are these docks all but abandoned?\n\nThe rangari scouts up ahead report trouble. Bleeding Hollow scavengers are looting some abandoned buildings to the northwest, and an encampment of warlock cultists lurk near the Dark Portal. Let's find out what we can and meet up with our scouts.", objectives = "Find any information on the forces deployed in the area and meet with the scouts afterwards.", completion = "Our forces can finish driving off the remaining lurkers. But there's another problem up ahead." }
WordHunterWoW_QuestEN[38437] = { title = "Max-level Choice Tracker: Tanaan 6.2 - The Fel Forge", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[38438] = { title = "Max-level Choice Tracker: Tanaan 6.2 - The Fel Forge", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[38439] = { title = "Assault on the Fel Forge", description = "The Iron Horde continue to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don't cut off the flow of supplies then we risk losing control of our plans in Tanaan.\n\nA strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.", objectives = "Assault the Iron Horde reinforcements at Ironhold Harbor in Tanaan Jungle." }
WordHunterWoW_QuestEN[38440] = { title = "Assault on The Fel Forge", description = "The Iron Horde is growing stronger each day as their war machines are empowered with fel magic. We have even obtained word that they are constructing a Fel Reaver!\n\nHead to the Fel Forge and destroy their forces before we are overwhelmed.", objectives = "Assault the Iron Horde forces at the Fel Forge in Tanaan Jungle.", progress = "How goes the assault, sir?", completion = "Welcome back, commander. Our scouts just returned with word of your success.\n\nWell done!" }
WordHunterWoW_QuestEN[38441] = { title = "Assault on The Fel Forge", description = "The Iron Horde is growing stronger each day as their war machines are empowered with fel magic. We have even obtained word that they are constructing a Fel Reaver!\n\nHead to the Fel Forge and destroy their forces before we are overwhelmed.", objectives = "Assault the Iron Horde forces at the Fel Forge in Tanaan Jungle.", completion = "Word of your success has already been passed on by our scouts. \n\nLok'tar!" }
WordHunterWoW_QuestEN[38442] = { title = "A Worthy Challenger", description = "", objectives = "" }
WordHunterWoW_QuestEN[38443] = { title = "Journey to the Repose", description = "For now, the Illidari can hold the line against the Legion. We will return later to help them drive the Legion from the upper reaches of Faronaar. You and I must concentrate on the Pillars of Creation if the Tomb of Sargeras is to be resealed.\n\nYour saving of Stellagosa is fortuitous. Surely if anyone knows where a Pillar of Creation is, it will be her grandfather, Senegos.\n\nThe Azurewing Repose is to the northeast. I will meet you there, {name}.", objectives = "Speak with Archmage Khadgar at the Azurewing Repose.", completion = "He is... he's dying! Senegos is possibly the oldest dragon alive. We cannot simply let him slip away.\n\nThere is something not quite right with the magic energy here, I can feel it." }
WordHunterWoW_QuestEN[38444] = { title = "In, Through, and Beyond!", description = "Gul'dan seems to have concentrated his defenses on this chokepoint. The guns up ahead are unlike anything we've seen before - they're empowered with fel energy.\n\nOur enemies think this pass is impregnable. Let's prove them wrong, commander! If we can break through, the terrain ahead will make an excellent stronghold. Destroy that cannon!", objectives = "Destroy the Fel Defense Cannon covering the gate.", completion = "Don't worry, I have a taskforce coming in a bit to clean the rest up. We should move before their runners get back to Gul'dan." }
WordHunterWoW_QuestEN[38445] = { title = "The Assault Base", description = "While you were playing with fel fire, I've located the perfect position for an assault outpost.\n\nFollow me and we can get this base started!", objectives = "Establish your assault base in Tanaan Jungle.", completion = "The easy part is done, now comes the hard part." }
WordHunterWoW_QuestEN[38446] = { title = "Commander in the Field!", description = "This battle will be won, but it will be hard fought. Our rangari did manage to get a few scouts out to the rest of the jungle though.\n\nPerhaps it is best you collect this intelligence yourself and see what this jungle holds for us all.", objectives = "Get reports from various scouts in Tanaan Jungle.", progress = "There's a lot to see here isn't there?", completion = "This will be a difficult campaign to be sure." }
WordHunterWoW_QuestEN[38449] = { title = "Assault on the Temple of Sha'naar", description = "Up in the hills of Tanaan Jungle, the Sargerei have converted a once-sacred temple into a den of demonic summoning.\n\nWe must attack them now, before their rituals complete. The longer we delay, the stronger our enemy grows.", objectives = "Assault the Sargerei forces at the Temple of Sha'naar in Tanaan Jungle.", completion = "Welcome back, General. Our scouts just returned with word of your success.\n\nWell done!" }
WordHunterWoW_QuestEN[38451] = { title = "Vignette: Geir Gutslice", description = "", objectives = "" }
WordHunterWoW_QuestEN[38452] = { title = "Vignette: Hidden Demon", description = "", objectives = "" }
WordHunterWoW_QuestEN[38453] = { title = "Garrison Campaign: The Bane of the Bleeding Hollow", description = "Commander, now that we've had time to get scouts all over the jungle we have heard some news near Zeth'Gol.\n\nIt appears that somebody else has a vendetta against the Bleeding Hollow and has been... hunting... them. Their hunters are closing in on the assassin.\n\nYou know what they say about \"the enemy of my enemy...\" We should collect their tracking maps and try to find the killer first!", objectives = "Collect tracking maps to find the location of the killer." }
WordHunterWoW_QuestEN[38454] = { title = "Unfortunate Circumstances", description = "The Illidari ask us to trust them, but all I see is failure. Look around... this entire city has been lost!\n\nI tracked down the pit lord Malinoth here and brought what few of my men I had with me to put an end to this depravity. They were not enough.\n\nThe brute threw us in this cage and was 'saving us for later.' We need your help, <name>.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Free Lady Liadrin." }
WordHunterWoW_QuestEN[38455] = { title = "Frenzied Furbolgs", description = "I would help you seek audience with the Archdruid, but we have a difficult situation on our hands.\n\nThe nearby furbolgs have gone into a frenzied rage.\n\nFor days, it has been all we can do to protect our grove from their aggression.\n\nThey have cut off our access to the barrow dens, where the Archdruid and our clan sleep in the Emerald Dream.\n\nIn order to awaken them, we must first get past the furbolg.", objectives = "Kill 8 Smolderhide furbolgs.", completion = "The conflict against the furbolgs is abated, for now." }
WordHunterWoW_QuestEN[38457] = { title = "Vignette: Putre'thar", description = "", objectives = "" }
WordHunterWoW_QuestEN[38458] = { title = "Garrison Campaign: The Warlock", description = "Commander, you have a visitor. One of Gul'dan's warlocks just walked up to the base and surrendered. He says he has information of a terrible event that is about to occur.\n\nI suggest you speak with him immediately.", objectives = "Speak with the warlock at Vol'mar in Tanaan Jungle.", completion = "I was too late to give you the message. I am truly sorry. These poor shaman... if only I had known sooner!\n\nGul'dan has prepared everything for his ritual. He will use the cipher and his own fel magic to corrupt an elemental lord and use it to sunder the elemental link to the land. This will cause a massive upheaval across Draenor!" }
WordHunterWoW_QuestEN[38459] = { title = "The Ancient Trials", description = "<As the raven stares into your eyes, an odd voice fills your mind.>\n\nI know who you are, champion, and I know what you seek.\n\nCome to me, if you think yourself truly worthy.", objectives = "Find Havi near Aggramar's Vault.", completion = "I'm sure your head is filled with questions. Answers will come, in time.\n\nI am Havi, and my words are those of the Valarjar - the glorious keepers of the Halls of Valor. \n\nYou will need my help if it is the Aegis you seek. Oh yes, I know your goals outsider. As I know many things..." }
WordHunterWoW_QuestEN[38460] = { title = "Let's Make A Deal", description = "Hey there!\n\nYou seem like a gullib- er... um... \"intelligent\" type.\n\nI propose a deal.\n\nI need a minion to be my muscle to help me acquire a few special... \"ingredients\" for a ritual.\n\nIn exchange, I'll give you my former master to do with whatever you demon-slaying types do with demons.\n\nIf you are interested, just sign here. In blood, please.", objectives = "Sign Daglop's contract.", progress = "Yeah! Yeah! You read the contract? I made it myself. Really good binding clauses in there.", completion = "At last! A minion of my very own!" }
WordHunterWoW_QuestEN[38461] = { title = "Vignette: Guarms Mate (Fenri)", description = "", objectives = "" }
WordHunterWoW_QuestEN[38462] = { title = "Breaching the Barrier", description = "The ritual site is already prepared, and it is protected by a barrier... one that I created. I can destroy the barrier, but I will need three items currently in use at Forge Camp Vengeance.\n\nIf you can get those ritual items, I will meet you at the Corrupted Refuge and remove the barrier. Even if it kills me.", objectives = "Collect the Black Candle, the Tome of Protection, and the Shadowblade at the Fel Forge and bring them to Oronok.", completion = "Not a moment too soon. He has summoned something, I fear the ritual is close to complete." }
WordHunterWoW_QuestEN[38463] = { title = "The Cipher of Damnation", description = "Your ally and I will remove this barrier now, though it will take a greater part of our strength. What lies beyond will not be easy.\n\nGul'dan will have empowered an elemental lord with the Cipher, driving it insane. He will use it to destroy the link between the elements and Draenor. If you destroy that elemental, we could recover the Cipher.", objectives = "Get Oronok and your ally to destroy the barrier, then stop Gul'dan.", completion = "You have saved us all. The Cipher has become fragmented with Cyrukh's death. This means its guardians can hide the shards all over Draenor so the chances of piecing it together will be impossible.\n\nThis victory will echo through the halls of your warriors and spur them to greater deeds. Gul'dan can continue plotting... he will fail..." }
